function exportDevicesCsv(devices: DeviceView[]) {
  const header = [
    'N┬░ s├®rie',
    'Type',
    'Statut',
    'Organisation',
    'V├®hicule',
    'Chauffeur',
    'IMEI',
    'Mod├¿le',
    'Firmware',
    'Batterie',
  ]
  const rows = devices.map((d) => [
    d.serial,
    d.type,
    d.status,
    d.orgName,
    d.vehiclePlate ?? '',
    d.driverName ?? '',
    d.imei ?? '',
    d.model ?? '',
    d.firmware ?? '',
    d.batteryStatus ?? '',
  ])
  const csv = [header, ...rows]
    .map((row) =>
      row
        .map((cell) => `"${String(cell).split('"').join('""')}"`)
        .join(';'),
    )
    .join('\r\n')
  const blob = new Blob([`\ufeff${csv}`], {
    type: 'text/csv;charset=utf-8;',
  })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = `appareils-${new Date().toISOString().slice(0, 10)}.csv`
  document.body.appendChild(link)
  link.click()
  document.body.removeChild(link)
  URL.revokeObjectURL(url)
}

function FilterChip({
  label,
  count,
  active,
  onClick,
}: {
  label: string
  count: number
  active: boolean
  onClick: () => void
}) {
  return (
    <Button
      type='button'
      variant={active ? 'default' : 'outline'}
      size='sm'
      className={cn(
        'h-10 rounded-full px-4 text-sm shadow-xs',
        active
          ? 'border-transparent shadow-sm'
          : 'border-transparent bg-background/85 hover:bg-muted/35'
      )}
      onClick={onClick}
    >
      <span>{label}</span>
      <Badge
        className={cn(
          'ms-2 rounded-full px-1.5 py-0 text-[10px]',
          active
            ? 'bg-primary-foreground/20 text-primary-foreground'
            : 'bg-muted text-muted-foreground'
        )}
      >
        {count}
      </Badge>
    </Button>
  )
}

