const DEFAULT_VALUES: PickupWizardValues = {
  marketeur_org_id: '',
  source_site_id: '',
  destination_site_id: '',
  requested_quantity: 0,
  type: 'VRAC',
}

function defaultValues(): PickupWizardValues {
  const values = { ...DEFAULT_VALUES, marketeur_org_id: defaultMarketeurOrg() }
  const scope = getScope(useAuthStore.getState().user)
  if (scope.view !== 'org' && scope.siteIds.length > 0) {
    // Enl├¿vement origin must be a supply point / filling centre. Prefer a site
    // of that function within the actor's scope; fall back to any active site.
    const supplyOrigin = sites.find(
      (s) => scope.siteIds.includes(s.id) && s.is_active !== false && isSupplyOrigin(s),
    )
    const firstSite = supplyOrigin ?? sites.find((s) => s.id === scope.siteIds[0] && s.is_active !== false)
    if (firstSite) values.source_site_id = firstSite.id
  }
  return values
}

export function PickupsCreateWizard({
  open,
  onOpenChange,
  onCreated,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
  onCreated: (pickup: PickupRequest, vehicleIds: string[]) => void
}) {
  const form = useForm<PickupWizardValues>({
    resolver: zodResolver(pickupWizardSchema),
    defaultValues: defaultValues(),
  })
  const [step, setStep] = useState(1)
  const [selectedVehicles, setSelectedVehicles] = useState<string[]>([])
  const [submitting, setSubmitting] = useState(false)

  const sourceSiteId = form.watch('source_site_id')
  const type = form.watch('type')
  const requestedQuantity = form.watch('requested_quantity')
  const marketeurOrgId = form.watch('marketeur_org_id')

  const scope = useMemo(() => getScope(useAuthStore.getState().user), [])
  const canChooseOrg = scope.view === 'org'

  const marketeurOptions = useMemo(() => {
    if (canChooseOrg) return MARKET_EUR_ORGS
    return MARKET_EUR_ORGS.filter((o) => o.id === scope.orgId)
  }, [canChooseOrg, scope.orgId])

  const sourceOptions = useMemo(() => {
    const active = sites.filter((s) => s.is_active !== false)
    if (canChooseOrg) return active.filter(isSupplyOrigin)
    const siteIds = new Set(scope.siteIds)
    return active.filter((s) => siteIds.has(s.id) && isSupplyOrigin(s))
  }, [canChooseOrg, scope.siteIds])
  const destOptions = useMemo(
    () => sites.filter((s) => s.is_active !== false && s.id !== sourceSiteId),
    [sourceSiteId],
  )

  const recommendations = useMemo<VehicleRecommendation[]>(() => {
    if (step !== 2 || requestedQuantity <= 0) return []
    return recommendVehicles({
      quantity: requestedQuantity,
      type,
      org_id: marketeurOrgId,
      vehicles: curated.vehicles,
    })
  }, [step, requestedQuantity, type, marketeurOrgId])

  function toggleVehicle(id: string) {
    setSelectedVehicles((prev) =>
      prev.includes(id) ? prev.filter((v) => v !== id) : [...prev, id],
    )
  }

  async function submit() {
    if (step === 1) {
      const valid = await form.trigger()
      if (!valid) return
      setStep(2)
      return
    }
    setSubmitting(true)
    try {
      const data = form.getValues()
      const created = usePickupsStore.getState().createPickup({
        marketeur_org_id: data.marketeur_org_id,
        source_site_id: data.source_site_id,
        destination_site_id: data.destination_site_id,
        requested_quantity: data.requested_quantity,
      })
      onCreated(created, selectedVehicles)
      toast.success(
        `Requ├¬te ${created.id} cr├®├®e en brouillon` +
          (selectedVehicles.length > 0
            ? ` ÔÇö ${selectedVehicles.length} v├®hicule(s) assign├®(s)`
            : ''),
      )
      onOpenChange(false)
      reset()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Impossible de cr├®er la requ├¬te'
      toast.error(message === PERMISSION_DENIED ? 'Acc├¿s refus├® pour ce site.' : message)
    } finally {
      setSubmitting(false)
    }
  }

  function reset() {
    setStep(1)
    form.reset(defaultValues())
    setSelectedVehicles([])
  }

  return (
    <Dialog open={open} onOpenChange={(o) => { if (!o) onOpenChange(false) }}>
      <DialogContent className='sm:max-w-lg'>
        <DialogHeader>
          <DialogTitle>
            {step === 1 ? 'Nouvelle requ├¬te de ramassage' : 'S├®lection des v├®hicules'}
          </DialogTitle>
        </DialogHeader>

        {step === 1 ? (
          <Form {...form}>
            <div className='space-y-4 py-2'>
              <div className='flex gap-3'>
                <FormField
                  control={form.control}
                  name='type'
                  render={({ field }) => (
                    <FormItem className='flex-1'>
                      <FormLabel>Type de cargaison</FormLabel>
                      <FormControl>
                        <Select
                          value={field.value}
                          onValueChange={(v) => field.onChange(v as VehicleType)}
                        >
                          <SelectTrigger className='w-full'>
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            {Object.entries(TYPE_LABELS).map(([value, label]) => (
                              <SelectItem key={value} value={value}>{label}</SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name='requested_quantity'
                  render={({ field }) => (
                    <FormItem className='flex-1'>
                      <FormLabel>Quantit├®</FormLabel>
                      <FormControl>
                        <Input
                          type='number'
                          min={0}
                          step={type === 'VRAC' ? 0.5 : 1}
                          value={field.value === 0 ? '' : field.value}
                          placeholder={type === 'VRAC' ? 'TM' : 'btl'}
                          onChange={(e) =>
                            field.onChange(e.target.value === '' ? 0 : Number(e.target.value))
                          }
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>

              <FormField
                control={form.control}
                name='marketeur_org_id'
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Marketeur</FormLabel>
                    <FormControl>
                      <Select value={field.value} onValueChange={field.onChange} disabled={!canChooseOrg}>
                        <SelectTrigger className='w-full'>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {marketeurOptions.map((o) => (
                            <SelectItem key={o.id} value={o.id}>{o.name}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name='source_site_id'
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Site source</FormLabel>
                    <FormControl>
                      <Select
                        value={field.value || undefined}
                        disabled={!canChooseOrg}
                        onValueChange={(v) => {
                          field.onChange(v)
                          form.setValue('destination_site_id', '')
                        }}
                      >
                        <SelectTrigger className='w-full'>
                          <SelectValue placeholder='ÔÇö S├®lectionner ÔÇö' />
                        </SelectTrigger>
                        <SelectContent>
                          {sourceOptions.map((s) => (
                            <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name='destination_site_id'
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Site destination</FormLabel>
                    <FormControl>
                      <Select
                        value={field.value || undefined}
                        onValueChange={field.onChange}
                      >
                        <SelectTrigger className='w-full'>
                          <SelectValue placeholder='ÔÇö S├®lectionner ÔÇö' />
                        </SelectTrigger>
                        <SelectContent>
                          {destOptions.map((s) => (
                            <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>
          </Form>
        ) : (
          <div className='space-y-4 py-2'>
            <p className='text-sm text-muted-foreground'>
              V├®hicules <strong>{TYPE_LABELS[type]}</strong> du marketeur capables de
              transporter <strong>{requestedQuantity}</strong>{' '}
              {type === 'VRAC' ? 'TM' : 'btl'}.
            </p>

            {recommendations.length === 0 ? (
              <div className='rounded-md border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800 dark:border-amber-900 dark:bg-amber-950 dark:text-amber-200'>
                Aucun v├®hicule de capacit├® suffisante trouv├® pour cette quantit├®.
              </div>
            ) : (
              <ul className='space-y-2'>
                {recommendations.map(({ vehicle, fitRatio, spareCapacity }) => (
                  <li key={vehicle.id}>
                    <button
                      type='button'
                      onClick={() => toggleVehicle(vehicle.id)}
                      className={`flex w-full items-center justify-between gap-3 rounded-md border p-3 text-left text-sm transition-colors ${
                        selectedVehicles.includes(vehicle.id)
                          ? 'border-primary bg-primary/5'
                          : 'border-border hover:bg-muted/40'
                      }`}
                    >
                      <span className='flex items-center gap-2 font-medium'>
                        <Truck className='size-4 text-primary' />
                        {vehicle.license_plate}
                      </span>
                      <span className='flex items-center gap-3 text-xs text-muted-foreground'>
                        <span>
                          Capacit├® {type === 'VRAC'
                            ? `${vehicle.max_volume} TM`
                            : `${vehicle.max_bottle_count} btl`}
                        </span>
                        <span>Reste {type === 'VRAC' ? `${spareCapacity} TM` : `${spareCapacity} btl`}</span>
                        <span>{Math.round(fitRatio * 100)}%</span>
                        <span
                          className={`flex size-5 items-center justify-center rounded-full border ${
                            selectedVehicles.includes(vehicle.id)
                              ? 'border-primary bg-primary text-primary-foreground'
                              : 'border-muted-foreground/30'
                          }`}
                        >
                          {selectedVehicles.includes(vehicle.id) && <Check className='size-3.5' />}
                        </span>
                      </span>
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </div>
        )}

        <DialogFooter className='flex items-center justify-between gap-2'>
          <div className='flex items-center gap-2'>
            {step === 2 && (
              <Button variant='ghost' onClick={() => setStep(1)} className='gap-1'>
                <ArrowLeft className='size-4' /> Retour
              </Button>
            )}
          </div>
          <div className='flex items-center gap-2'>
            <Button variant='outline' onClick={() => onOpenChange(false)}>Annuler</Button>
            {step === 1 ? (
              <Button onClick={submit} className='gap-1'>
                Suivant <ArrowRight className='size-4' />
              </Button>
            ) : (
              <Button onClick={submit} disabled={submitting || selectedVehicles.length === 0} className='gap-1'>
                Cr├®er la requ├¬te
              </Button>
            )}
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

import { useMemo, useState } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  type SortingState,
  useReactTable,
} from '@tanstack/react-table'
import { DataTablePagination, DataTableToolbar } from '@lpg/ui'
import { cn } from '@/lib/utils'
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from '@/components/ui/table'
import { getPickupsColumns } from './pickups-columns'
import { pickupStatusOptions, type Pickup } from '../data/pickups'

export function PickupsTable({
  rows,
  onOpenDetails,
}: {
  rows: Pickup[]
  onOpenDetails: (row: Pickup) => void
}) {
  const [sorting, setSorting] = useState<SortingState>([])
  const [pagination, setPagination] = useState({ pageIndex: 0, pageSize: 10 })

  const columns = useMemo(() => getPickupsColumns({ onOpenDetails }), [onOpenDetails])

  const table = useReactTable({
    data: rows,
    columns,
    state: { sorting, pagination },
    onSortingChange: setSorting,
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
  })

  return (
    <div className='flex flex-1 flex-col gap-4'>
      <DataTableToolbar
        table={table}
        searchPlaceholder='Rechercher une r├®f├®rence, marketeur...'
        searchKey='reference'
        filters={[{ columnId: 'pickup_status', title: 'Statut', options: pickupStatusOptions }]}
      />
      <div className='overflow-hidden rounded-md border'>
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((hg) => (
              <TableRow key={hg.id}>
                {hg.headers.map((header) => (
                  <TableHead key={header.id} className={cn(header.column.columnDef.meta?.className)}>
                    {header.isPlaceholder ? null : flexRender(header.column.columnDef.header, header.getContext())}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow key={row.id}>
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={columns.length} className='h-24 text-center'>
                  Aucun enl├¿vement.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <DataTablePagination table={table} />
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getFacetedRowModel,
  getFacetedUniqueValues,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  type SortingState,
  type VisibilityState,
  useReactTable,
} from '@tanstack/react-table'
import { cn } from '@/lib/utils'
import { type NavigateFn, useTableUrlState } from '@/hooks/use-table-url-state'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { DataTablePagination, DataTableToolbar } from '@/components/data-table'
import {
  entityTypeLabels,
  recomputeView,
  type RiskScoreView,
} from '../data/recompute'
import { DataTableBulkActions } from './data-table-bulk-actions'
import { getRecomputeColumns } from './recompute-columns'

type RecomputeTableProps = {
  data: RiskScoreView[]
  search: Record<string, unknown>
  navigate: NavigateFn
}

export function RecomputeTable({ data, search, navigate }: RecomputeTableProps) {
  const [rowSelection, setRowSelection] = useState({})
  const [columnVisibility, setColumnVisibility] = useState<VisibilityState>({})
  const [sorting, setSorting] = useState<SortingState>([])
  const columns = useMemo(() => getRecomputeColumns(), [])

  const entityOptions = useMemo(() => {
    const set = new Set<string>()
    for (const item of recomputeView) set.add(item.entityType)
    return Array.from(set, (type) => ({
      label: entityTypeLabels[type as keyof typeof entityTypeLabels] ?? type,
      value: type,
    }))
  }, [])

  const {
    columnFilters,
    onColumnFiltersChange,
    pagination,
    onPaginationChange,
    ensurePageInRange,
  } = useTableUrlState({
    search,
    navigate,
    pagination: { defaultPage: 1, defaultPageSize: 10 },
    globalFilter: { enabled: false },
    columnFilters: [
      { columnId: 'id', searchKey: 'q', type: 'string' },
      { columnId: 'entityType', searchKey: 'type', type: 'array' },
      { columnId: 'level', searchKey: 'level', type: 'array' },
    ],
  })

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      pagination,
      rowSelection,
      columnFilters,
      columnVisibility,
    },
    enableRowSelection: true,
    onPaginationChange,
    onColumnFiltersChange,
    onRowSelectionChange: setRowSelection,
    onSortingChange: setSorting,
    onColumnVisibilityChange: setColumnVisibility,
    getPaginationRowModel: getPaginationRowModel(),
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFacetedRowModel: getFacetedRowModel(),
    getFacetedUniqueValues: getFacetedUniqueValues(),
  })

  useEffect(() => {
    ensurePageInRange(table.getPageCount())
  }, [table, ensurePageInRange])

  return (
    <div
      className={cn(
        'max-sm:has-[div[role="toolbar"]]:mb-16',
        'flex flex-1 flex-col gap-4'
      )}
    >
      <DataTableToolbar
        table={table}
        searchPlaceholder='Rechercher score, entit├®, niveau...'
        searchKey='id'
        filters={[
          {
            columnId: 'entityType',
            title: 'Type entit├®',
            options: entityOptions,
          },
        ]}
      />

      <div className='overflow-hidden rounded-md border'>
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id} className='group/row'>
                {headerGroup.headers.map((header) => (
                  <TableHead
                    key={header.id}
                    colSpan={header.colSpan}
                    className={cn(
                      'bg-background group-hover/row:bg-muted group-data-[state=selected]/row:bg-muted',
                      header.column.columnDef.meta?.className,
                      header.column.columnDef.meta?.thClassName
                    )}
                  >
                    {header.isPlaceholder
                      ? null
                      : flexRender(
                          header.column.columnDef.header,
                          header.getContext()
                        )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && 'selected'}
                  className='group/row'
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell
                      key={cell.id}
                      className={cn(
                        'bg-background group-hover/row:bg-muted group-data-[state=selected]/row:bg-muted',
                        cell.column.columnDef.meta?.className,
                        cell.column.columnDef.meta?.tdClassName
                      )}
                    >
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext()
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={columns.length}
                  className='h-24 text-center'
                >
                  Aucun score de risque ne correspond aux filtres.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <DataTablePagination table={table} className='mt-auto' />
      <DataTableBulkActions table={table} />
    </div>
  )
}

