                <TableRow key={row.id}>
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={columns.length} className='h-24 text-center'>
                  Aucun redressement.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <DataTablePagination table={table} />
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { currentLang } from '@/lib/i18n/formatters'
import { FileBarChart, FileDown, Loader2, Plus, RefreshCw } from 'lucide-react'
import { toast } from 'sonner'
import { Badge } from '@lpg/ui'
import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { PageHeader } from '@/components/layout/page-header'
import { KpiTile, PageShell, SectionCard } from '@/components/layout/page'
import {
  EntityFormSheet,
  useEntityPermission,
  field,
} from '@/components/entity-crud'
import type { ReportFormat, ReportType } from '@lpg/types'
import {
  formatFileSize,
  getReportSummary,
  getReports,
  reportStatusLabels,
  reportTypeLabels,
  type ReportView,
} from './data/reports'
import { useReportsStore } from './data/reports-store'

const TYPE_OPTIONS = (
  Object.keys(reportTypeLabels) as ReportType[]
).map((value) => ({ label: reportTypeLabels[value], value }))

const FORMAT_OPTIONS: { label: string; value: ReportFormat }[] = [
  { label: 'Excel', value: 'EXCEL' },
  { label: 'PDF', value: 'PDF' },
  { label: 'CSV', value: 'CSV' },
]

const requestFields = [
  field.text('name', 'Nom du rapport', { required: true }),
  field.select('type', 'Type', TYPE_OPTIONS, { required: true }),
  field.select('format', 'Format', FORMAT_OPTIONS, { required: true }),
]

export function ReportsPage() {
  const perm = useEntityPermission('reports')
  const reports = useReportsStore((s) => s.reports)
  const hasPending = useReportsStore((s) => s.hasPending)
  const [creating, setCreating] = useState(false)
  const [detail, setDetail] = useState<ReportView | null>(null)

  const view = useMemo(() => getReports(reports), [reports])
  const summary = useMemo(() => getReportSummary(), [view])

  // Poll pending/generating reports to their terminal state.
  useEffect(() => {
    if (!hasPending) return
    const interval = setInterval(() => {
      useReportsStore.getState().tick()
    }, 3000)
    return () => clearInterval(interval)
  }, [hasPending])

  async function handleRequest(values: Record<string, unknown>) {
    useReportsStore
      .getState()
      .requestReport(
        String(values.name),
        values.type as ReportType,
        values.format as ReportFormat,
      )
    toast.success('Rapport demand├®. G├®n├®ration en coursÔÇª')
    setCreating(false)
  }

  return (
    <PageShell>
      <PageHeader
        title='Rapports & exports'
        description='Rapports asynchrones : g├®n├®ration puis t├®l├®chargement.'
        actions={
          perm.canCreate ? (
            <Button onClick={() => setCreating(true)}>
              <Plus className='mr-1 h-4 w-4' /> Demander un rapport
            </Button>
          ) : undefined
        }
      />

      <div className='grid gap-4 sm:grid-cols-4'>
        <KpiTile label='Rapports' value={String(summary.total)} />
        <KpiTile label='Pr├¬ts' value={String(summary.ready)} />
        <KpiTile label='En cours' value={String(summary.pending)} />
        <KpiTile label='├ëchecs' value={String(summary.failed)} />
      </div>

      <SectionCard
        title='Rapports g├®n├®r├®s'
        description='Les rapports en attente sont rafra├«chis automatiquement.'
        actions={
          hasPending ? (
            <span className='inline-flex items-center gap-1 text-xs text-muted-foreground'>
              <Loader2 className='size-3.5 animate-spin' /> G├®n├®ration en coursÔÇª
            </span>
          ) : (
            <Button
              variant='ghost'
              size='sm'
              className='h-7 px-2 text-xs'
              onClick={() => useReportsStore.getState().tick()}
            >
              <RefreshCw className='mr-1 size-3.5' /> Rafra├«chir
            </Button>
          )
        }
      >
        <div className='space-y-2'>
          {view.length === 0 && (
            <p className='text-sm text-muted-foreground'>Aucun rapport.</p>
          )}
          {view.map((report) => (
            <ReportRow
              key={report.id}
              report={report}
              onOpen={() => setDetail(report)}
              onDownload={() => {
                useReportsStore.getState().downloadReport(report.id)
                toast.success(`T├®l├®chargement de ┬½ ${report.name} ┬╗ lanc├®.`)
              }}
            />
          ))}
        </div>
      </SectionCard>

      <EntityFormSheet
        open={creating}
        onOpenChange={setCreating}
        title='Demander un rapport'
        description='Le rapport est g├®n├®r├® de fa├ºon asynchrone puis devient t├®l├®chargeable.'
        fields={requestFields}
        onSubmit={handleRequest}
        onCancel={() => setCreating(false)}
        submitLabel='Demander'
      />

      <ReportDetailsDialog
        report={detail}
        onClose={() => setDetail(null)}
        onDownload={() => {
          if (!detail) return
          useReportsStore.getState().downloadReport(detail.id)
          toast.success(`T├®l├®chargement de ┬½ ${detail.name} ┬╗ lanc├®.`)
        }}
      />
    </PageShell>
  )
}

function ReportRow({
  report,
  onOpen,
  onDownload,
}: {
  report: ReportView
  onOpen: () => void
  onDownload: () => void
}) {
  const ready = report.status === 'READY'
  const busy = report.status === 'PENDING' || report.status === 'GENERATING'
  return (
    <div className='flex flex-wrap items-center justify-between gap-2 rounded-lg border p-3'>
      <button type='button' onClick={onOpen} className='flex min-w-0 items-center gap-2 text-left'>
        <FileBarChart className='size-4 shrink-0 text-primary' />
        <div className='min-w-0'>
          <p className='truncate text-sm font-medium'>{report.name}</p>
          <p className='truncate text-xs text-muted-foreground'>
            {report.typeLabel} / {report.format}
            {report.generatedBy && <> / {report.generatedBy}</>}
          </p>
        </div>
      </button>
      <div className='flex flex-wrap items-center gap-1.5'>
        {report.generatedAt && (
          <span className='text-xs text-muted-foreground'>
            {report.generatedAt.slice(0, 10)}
          </span>
        )}
        {report.fileSize != null && (
          <span className='text-xs text-muted-foreground'>
            {formatFileSize(report.fileSize)}
          </span>
        )}
        <Badge variant={ready ? 'default' : busy ? 'secondary' : 'outline'}>
          {busy && <Loader2 className='mr-1 size-3 animate-spin' />}
          {reportStatusLabels[report.status]}
        </Badge>
        {ready && (
          <Button
            variant='outline'
            size='icon'
            className='size-7'
            aria-label='T├®l├®charger'
            onClick={onDownload}
          >
            <FileDown className='size-3.5 text-emerald-600' />
          </Button>
        )}
      </div>
    </div>
  )
}

function ReportDetailsDialog({
  report,
  onClose,
  onDownload,
}: {
  report: ReportView | null
  onClose: () => void
  onDownload: () => void
}) {
  const ready = report?.status === 'READY'
  return (
    <Dialog open={report !== null} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className='max-w-md'>
        <DialogHeader>
          <DialogTitle>{report?.name}</DialogTitle>
          <DialogDescription>
            Fiche d├®taill├®e du rapport et de sa disponibilit├®.
          </DialogDescription>
        </DialogHeader>
        {report && (
          <div className='space-y-3 text-sm'>
            <dl className='grid grid-cols-2 gap-x-4 gap-y-2'>
              <dt className='text-muted-foreground'>Type</dt>
              <dd>{report.typeLabel}</dd>
              <dt className='text-muted-foreground'>Format</dt>
              <dd>{report.format}</dd>
              <dt className='text-muted-foreground'>Statut</dt>
              <dd>
                <Badge variant={ready ? 'default' : 'outline'}>
                  {reportStatusLabels[report.status]}
                </Badge>
              </dd>
              <dt className='text-muted-foreground'>G├®n├®r├® le</dt>
              <dd>{report.generatedAt ? new Date(report.generatedAt).toLocaleString(currentLang()) : 'ÔÇö'}</dd>
              <dt className='text-muted-foreground'>Par</dt>
              <dd>{report.generatedBy ?? 'ÔÇö'}</dd>
              <dt className='text-muted-foreground'>Expire le</dt>
              <dd>{report.expiresAt ? new Date(report.expiresAt).toLocaleString(currentLang()) : 'ÔÇö'}</dd>
              <dt className='text-muted-foreground'>Taille</dt>
              <dd>{formatFileSize(report.fileSize) || 'ÔÇö'}</dd>
            </dl>
            {ready && (
              <Button className='w-full' onClick={onDownload}>
                <FileDown className='mr-1 size-4' /> T├®l├®charger
              </Button>
            )}
          </div>
        )}
      </DialogContent>
    </Dialog>
  )
}

import { useEffect, useMemo, useState } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getExpandedRowModel,
  getFacetedRowModel,
  getFacetedUniqueValues,
  getFilteredRowModel,
  getGroupedRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  type ColumnFiltersState,
  type GroupingState,
  type PaginationState,
  type SortingState,
  type VisibilityState,
  useReactTable,
} from '@tanstack/react-table'
import { cn } from '@/lib/utils'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { DataTablePagination, DataTableToolbar } from '@/components/data-table'
import {
  getRfidTagLocationOptions,
  rfidTagStatusOptions,
  type RfidTagView,
} from '../data/rfid-tags'
import { getRfidTagsColumns } from './rfid-tags-columns'
import { DataTableBulkActions as RfidTagsBulkActions } from './data-table-bulk-actions'

type RfidTagsTableProps = {
  data: RfidTagView[]
  onOpenDetails: (tag: RfidTagView) => void
  onEdit?: (tag: RfidTagView) => void
  onDelete?: (tag: RfidTagView) => void
}

export function RfidTagsTable({
  data,
  onOpenDetails,
  onEdit,
  onDelete,
}: RfidTagsTableProps) {
  const [rowSelection, setRowSelection] = useState({})
  const [columnVisibility, setColumnVisibility] = useState<VisibilityState>({})
  const [sorting, setSorting] = useState<SortingState>([])
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([])
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: 0,
    pageSize: 10,
  })
  const [grouping, setGrouping] = useState<GroupingState>([])
  const [expanded, setExpanded] = useState({})

  const columns = useMemo(
    () => getRfidTagsColumns({ onOpenDetails, onEdit, onDelete }),
    [onOpenDetails, onEdit, onDelete]
  )

  const locationOptions = useMemo(() => getRfidTagLocationOptions(data), [data])

  // eslint-disable-next-line react-hooks/incompatible-library
  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      pagination,
      rowSelection,
      columnFilters,
      columnVisibility,
      grouping,
      expanded,
    },
    enableRowSelection: true,
    enableGrouping: true,
    onPaginationChange: setPagination,
    onColumnFiltersChange: setColumnFilters,
    onRowSelectionChange: setRowSelection,
    onSortingChange: setSorting,
    onColumnVisibilityChange: setColumnVisibility,
    onGroupingChange: setGrouping,
    onExpandedChange: setExpanded,
    getPaginationRowModel: getPaginationRowModel(),
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getExpandedRowModel: getExpandedRowModel(),
    getGroupedRowModel: getGroupedRowModel(),
    getFacetedRowModel: getFacetedRowModel(),
    getFacetedUniqueValues: getFacetedUniqueValues(),
  })

  useEffect(() => {
    setPagination((prev) => ({
      ...prev,
      pageIndex: Math.min(prev.pageIndex, Math.max(table.getPageCount() - 1, 0)),
    }))
  }, [table.getPageCount()])

  return (
    <div
      className={cn(
        'max-sm:has-[div[role="toolbar"]]:mb-16',
        'flex flex-1 flex-col gap-4'
      )}
    >
      <div className='flex flex-wrap items-center gap-3'>
        <DataTableToolbar
          table={table}
          searchPlaceholder='Rechercher tag RFID, bouteille, localisation...'
          searchKey='tag_id'
          filters={[
            {
              columnId: 'status',
              title: 'Statut',
              options: [...rfidTagStatusOptions],
            },
            {
              columnId: 'location',
              title: 'Localisation',
              options: locationOptions,
            },
          ]}
        />
        <div className='flex items-center gap-2'>
          <span className='text-xs text-muted-foreground'>Grouper par</span>
          <select
            value={grouping[0] ?? ''}
            onChange={(e) =>
              setGrouping(e.target.value ? [e.target.value] : [])
            }
            className='h-8 rounded-md border bg-background px-2 text-sm'
          >
            <option value=''>ÔÇö</option>
            <option value='status'>Statut</option>
          </select>
        </div>
      </div>

      <div className='overflow-hidden rounded-md border'>
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id} className='group/row'>
                {headerGroup.headers.map((header) => (
                  <TableHead
                    key={header.id}
                    colSpan={header.colSpan}
                    className={cn(
                      'bg-background group-hover/row:bg-muted group-data-[state=selected]/row:bg-muted',
                      header.column.columnDef.meta?.className,
                      header.column.columnDef.meta?.thClassName
                    )}
                  >
                    {header.isPlaceholder
                      ? null
                      : flexRender(
                          header.column.columnDef.header,
                          header.getContext()
                        )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && 'selected'}
                  className={cn(
                    'group/row',
                    row.getIsGrouped() && 'bg-muted/40 font-medium'
                  )}
                  onDoubleClick={() => {
                    if (!row.getIsGrouped()) onOpenDetails(row.original)
                  }}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell
                      key={cell.id}
                      className={cn(
                        'bg-background group-hover/row:bg-muted group-data-[state=selected]/row:bg-muted',
                        cell.column.columnDef.meta?.className,
                        cell.column.columnDef.meta?.tdClassName
                      )}
                    >
                      {cell.getIsGrouped() ? (
                        <button
                          type='button'
                          className='flex items-center gap-2 text-primary'
                          onClick={row.getToggleExpandedHandler()}
                        >
                          {row.getIsExpanded() ? 'Ôû╝' : 'ÔûÂ'}{' '}
                          {flexRender(
                            cell.column.columnDef.cell,
                            cell.getContext()
                          )}{' '}
                          ({row.subRows.length})
                        </button>
                      ) : cell.getIsPlaceholder() ? null : (
                        flexRender(
                          cell.column.columnDef.cell,
                          cell.getContext()
                        )
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={columns.length}
                  className='h-24 text-center'
                >
                  Aucun tag RFID ne correspond aux filtres.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <DataTablePagination table={table} className='mt-auto' />
      <RfidTagsBulkActions table={table} />
    </div>
  )
}

import { useMemo, useState } from 'react'
import { Badge } from '@/components/ui/badge'
import { Plus, Search } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'
import { RfidTagsTable } from './components/rfid-tags-table'
import { RfidTagDetailsSheet } from './components/rfid-tag-details-sheet'
import {
  getRfidTags as _getRfidTags,
  getRfidTagsView,
  rfidTagStatusLabels,
  rfidTagStatusOptions,
  type RfidTagView,
} from './data/rfid-tags'
import { EntityFormSheet, useEntityCrud } from '@/components/entity-crud'
import { rfidTagFields, rfidTagFromForm, rfidTagToForm } from './data/rfid-tags-crud'
import type { RfidTag } from '@lpg/types'
import { toast } from 'sonner'

export const getRfidTags = _getRfidTags
export type { RfidTag } from '@lpg/types'

type RfidTagFilter = 'all' | string

type RfidTagFilterDef = { label: string; value: string; count: number }

const ALL_STATUSES = rfidTagStatusOptions.map((option) => option.value)

export function RfidTagsPage() {
  const crud = useEntityCrud<RfidTag>('rfidTags', 'rfid', ['rfid-tags'])
  const tags = useMemo(() => getRfidTagsView(crud.list.data ?? _getRfidTags()), [crud.list.data])
  const [search, setSearch] = useState('')
  const [statusFilter, setStatusFilter] = useState<RfidTagFilter>('all')
  const [detailsTag, setDetailsTag] = useState<RfidTagView | null>(null)

  const handleViewDetails = (tag: RfidTagView) => setDetailsTag(tag)

  async function handleSubmit(values: Record<string, unknown>) {
    try {
      if (crud.editing) {
        await crud.updateMut.mutateAsync({ id: crud.editing.id, patch: rfidTagFromForm(values) })
        toast.success('Tag RFID mis ├á jour.')
      } else {
        await crud.createMut.mutateAsync(rfidTagFromForm(values) as Omit<RfidTag, 'id'>)
        toast.success('Tag RFID cr├®├®.')
      }
      crud.close()
    } catch {
      toast.error('├ëchec de lÔÇÖenregistrement.')
    }
  }

  const filteredTags = useMemo(() => {
    const query = search.trim().toLowerCase()
    if (!query) return tags
    return tags.filter((tag) => {
      const haystack = [tag.tag_id, tag.bottle_serial, tag.location]
        .filter(Boolean)
        .join(' ')
        .toLowerCase()
      return haystack.includes(query)
    })
  }, [tags, search])

  const visible =
    statusFilter === 'all'
      ? filteredTags
      : filteredTags.filter((tag) => tag.status === statusFilter)

  const filterDefs: RfidTagFilterDef[] = useMemo(() => {
    const counts: Record<string, number> = {}
    for (const tag of tags) {
      counts[tag.status] = (counts[tag.status] ?? 0) + 1
    }
    return [
      { label: 'Tous', value: 'all', count: tags.length },
      ...ALL_STATUSES.map((status) => ({
        label: rfidTagStatusLabels[status as keyof typeof rfidTagStatusLabels],
        value: status,
        count: counts[status] ?? 0,
      })),
    ]
  }, [tags])

  return (
    <main
      id='main-content'
      className='flex-1 space-y-4 bg-gradient-to-b from-slate-50 via-white to-slate-100 p-4 text-sm sm:p-6 dark:from-slate-950 dark:via-slate-950 dark:to-slate-900'
    >
      <section className='rounded-2xl border-transparent bg-background/88 p-3 shadow-sm backdrop-blur-sm sm:p-4'>
        <div className='flex flex-col gap-3 xl:flex-row xl:items-center xl:justify-between'>
          <div className='flex flex-wrap items-center gap-2'>
            <Badge
              variant='outline'
              className='border-transparent bg-background/90 px-3 py-1.5 text-xs shadow-xs'
            >
              {tags.length} tags RFID
            </Badge>
          </div>

          <div className='flex w-full flex-col gap-2 sm:w-auto sm:flex-row sm:items-center'>
            {crud.perm.canCreate && (
              <Button onClick={crud.openCreate}>
                <Plus className='mr-1 h-4 w-4' /> Nouveau tag
              </Button>
            )}
            <div className='relative w-full sm:w-[310px]'>
              <Search className='pointer-events-none absolute start-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground' />
              <Input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder='Rechercher tag RFID, bouteille, localisationÔÇª'
                className='h-9 ps-9'
              />
            </div>
          </div>
        </div>

        <div className='mt-4 flex flex-col gap-1'>
          <h1 className='text-[30px] leading-none font-semibold tracking-tight sm:text-3xl'>
            Registre des tags RFID
          </h1>
          <p className='inline-flex items-center gap-2 text-xs text-muted-foreground sm:text-sm'>
            Suivi du parc de tags RFID, de leur affectation ├á une bouteille et de
            leur ├®tat de circulation.
          </p>
        </div>
      </section>

      <section className='rounded-2xl border-transparent bg-background/88 p-4 shadow-sm backdrop-blur-sm'>
        <div className='flex flex-wrap gap-2.5'>
          {filterDefs.map((filter) => (
            <FilterChip
              key={filter.value}
              label={filter.label}
              count={filter.count}
              active={statusFilter === filter.value}
              onClick={() => setStatusFilter(filter.value)}
            />
          ))}
        </div>
      </section>

      <section className='space-y-4 rounded-xl border-transparent bg-background/92 p-4 shadow-sm'>
        <div className='flex flex-col gap-1 sm:flex-row sm:items-end sm:justify-between'>
          <div>
            <h2 className='text-xl font-semibold tracking-tight'>
              Liste des tags RFID
            </h2>
            <p className='text-sm text-muted-foreground'>
              Selectionnez un tag pour voir sa fiche detaillee et son
              affectation.
            </p>
          </div>
          <Badge
            variant='outline'
            className='border-transparent bg-muted/35 text-foreground'
          >
            {visible.length} / {tags.length} tags
          </Badge>
        </div>
        <RfidTagsTable
          data={visible}
          onOpenDetails={handleViewDetails}
          onEdit={(t) => crud.openEdit(t as unknown as RfidTag)}
          onDelete={(t) => crud.removeMut.mutateAsync(t.tag.id)}
        />
      </section>

      <RfidTagDetailsSheet
        tag={detailsTag}
        open={detailsTag !== null}
        onOpenChange={(open) => {
          if (!open) setDetailsTag(null)
        }}
      />

      <EntityFormSheet
        open={crud.creating || crud.editing !== null}
        onOpenChange={(open) => {
          if (!open) crud.close()
        }}
        title={crud.editing ? 'Modifier le tag RFID' : 'Nouveau tag RFID'}
        description={crud.editing ? 'Mettez ├á jour les informations du tag.' : 'Ajoutez un tag RFID au registre.'}
        fields={rfidTagFields}
        initial={crud.editing ? rfidTagToForm(crud.editing) : null}
        onSubmit={handleSubmit}
        onCancel={crud.close}
        submitting={crud.createMut.isPending || crud.updateMut.isPending}
      />
    </main>
  )
}

function FilterChip({
  label,
  count,
  active,
  onClick,
}: {
  label: string
  count: number
  active: boolean
  onClick: () => void
}) {
  return (
    <Button
      type='button'
      variant={active ? 'default' : 'outline'}
      size='sm'
      className={cn(
        'h-10 rounded-full px-4 text-sm shadow-xs',
        active
          ? 'border-transparent shadow-sm'
          : 'border-transparent bg-background/85 hover:bg-muted/35'
      )}
      onClick={onClick}
    >
      <span>{label}</span>
      <Badge
        className={cn(
          'ms-2 rounded-full px-1.5 py-0 text-[10px]',
          active
            ? 'bg-primary-foreground/20 text-primary-foreground'
            : 'bg-muted text-muted-foreground'
        )}
      >
        {count}
      </Badge>
    </Button>
  )
}

import { useMemo, useState } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getExpandedRowModel,
  getFilteredRowModel,
  getGroupedRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  type GroupingState,
  type ExpandedState,
  type SortingState,
  useReactTable,
} from '@tanstack/react-table'
import { DataTablePagination, DataTableToolbar } from '@lpg/ui'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from '@/components/ui/table'
import { getRiskScoreColumns } from './risk-scores-columns'
import { riskLevelOptions, type RiskScoreView } from '../data/risk-scores'

type GroupMode = 'level' | 'entity_type' | ''

const GROUP_OPTIONS: { value: GroupMode; label: string }[] = [
  { value: '', label: 'Aucun groupement' },
  { value: 'level', label: 'Niveau de risque' },
  { value: 'entity_type', label: 'Type dÔÇÖentit├®' },
]

export function RiskScoresTable({
  rows,
  onViewDetails,
}: {
  rows: RiskScoreView[]
  onViewDetails: (row: RiskScoreView) => void
}) {
  const [sorting, setSorting] = useState<SortingState>([])
  const [grouping, setGrouping] = useState<GroupingState>(['level'])
  const [expanded, setExpanded] = useState<ExpandedState>({})
  const [pagination, setPagination] = useState({ pageIndex: 0, pageSize: 10 })

  const columns = useMemo(() => getRiskScoreColumns(), [])

  const groupMode: GroupMode =
    grouping[0] === 'level' ? 'level' : grouping[0] === 'entity_type' ? 'entity_type' : ''

  const table = useReactTable({
    data: rows,
    columns,
    state: { sorting, pagination, grouping, expanded },
    onSortingChange: setSorting,
    onPaginationChange: setPagination,
    onGroupingChange: setGrouping,
    onExpandedChange: setExpanded,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getGroupedRowModel: getGroupedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getExpandedRowModel: getExpandedRowModel(),
  })

  const changeGrouping = (mode: GroupMode) => {
    setGrouping(mode ? [mode] : [])
    setExpanded({})
  }

  return (
    <div className='flex flex-1 flex-col gap-4'>
      <DataTableToolbar
        table={table}
        searchPlaceholder='Rechercher une entit├®...'
        searchKey='entity_name'
        filters={[{ columnId: 'level', title: 'Niveau', options: riskLevelOptions }]}
      />
      <div className='flex flex-wrap items-center gap-1'>
        <span className='text-sm text-muted-foreground'>Grouper par :</span>
        {GROUP_OPTIONS.map((option) => (
          <Button
            key={option.value}
            type='button'
            variant={groupMode === option.value ? 'secondary' : 'ghost'}
            size='sm'
            onClick={() => changeGrouping(option.value)}
          >
            {option.label}
          </Button>
        ))}
      </div>
      <div className='overflow-hidden rounded-md border'>
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((hg) => (
              <TableRow key={hg.id}>
                {hg.headers.map((header) => (
                  <TableHead key={header.id} className={cn(header.column.columnDef.meta?.className)}>
                    {header.isPlaceholder ? null : flexRender(header.column.columnDef.header, header.getContext())}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length ? (
              table.getRowModel().rows.map((row) => {
                if (row.getIsGrouped()) {
                  return (
                    <TableRow key={row.id} className='bg-muted/40'>
                      {row.getVisibleCells().map((cell) => (
                        <TableCell key={cell.id} colSpan={row.getVisibleCells().length}>
                          <button
                            type='button'
                            className='inline-flex items-center gap-2 text-left text-sm font-semibold'
                            onClick={row.getToggleExpandedHandler()}
                          >
                            <span className='text-muted-foreground'>
                              {row.getIsExpanded() ? 'Ôû¥' : 'Ôû©'}
                            </span>
                            {flexRender(cell.column.columnDef.cell, cell.getContext())}
                            <span className='text-xs font-normal text-muted-foreground'>
                              ({row.subRows.length})
                            </span>
                          </button>
                        </TableCell>
                      ))}
                    </TableRow>
                  )
                }
                return (
                  <TableRow
                    key={row.id}
                    className='cursor-pointer'
                    onClick={() => onViewDetails(row.original)}
                  >
                    {row.getVisibleCells().map((cell) => (
                      <TableCell key={cell.id}>
                        {flexRender(cell.column.columnDef.cell, cell.getContext())}
                      </TableCell>
                    ))}
                  </TableRow>
                )
              })
            ) : (
              <TableRow>
                <TableCell colSpan={columns.length} className='h-24 text-center'>
                  Aucun score.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <DataTablePagination table={table} className='mt-auto' />
    </div>
  )
}

import { useState, useEffect } from 'react'
import { Loader2, AlertCircle, Key, Eye, EyeOff } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Alert, AlertDescription } from '@/components/ui/alert'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { toast } from 'sonner'
import { verifySync } from 'otplib'

interface MFAChallengeDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  secret: string
  onVerify: (code: string) => Promise<boolean>
  onCancel: () => void
  isLoading?: boolean
  rememberDevice?: boolean
  onRememberDeviceChange?: (value: boolean) => void
}

export function MFAChallengeDialog({
  open,
  onOpenChange,
  secret,
  onVerify,
  onCancel,
  isLoading = false,
  rememberDevice = false,
  onRememberDeviceChange,
}: MFAChallengeDialogProps) {
  const [code, setCode] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [showCode, setShowCode] = useState(false)
  const [isVerifying, setIsVerifying] = useState(false)

  useEffect(() => {
    if (open) {
      setCode('')
      setError(null)
    }
  }, [open])

  const handleVerify = async () => {
    if (!code || code.length !== 6) {
      setError('Veuillez entrer le code ├á 6 chiffres')
      return
    }

    setIsVerifying(true)
    setError(null)

    try {
      // First verify locally with the secret (for demo)
      const isValidLocal = verifySync({ token: code, secret })

      // Then call the server verification
      const isValid = await onVerify(code)

      if (isValid && isValidLocal.valid) {
        onOpenChange(false)
        toast.success('Authentification r├®ussie')
      } else {
        setError('Code invalide ou expir├®. Veuillez r├®essayer.')
      }
    } catch (err) {
      setError('Erreur lors de la v├®rification. Veuillez r├®essayer.')
      console.error(err)
    } finally {
      setIsVerifying(false)
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !isVerifying) {
      handleVerify()
    }
  }

  if (!open) return null

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className='sm:max-w-md'>
        <DialogHeader>
          <DialogTitle className='flex items-center gap-2'>
            <Key className='h-5 w-5 text-primary' />
            Authentification ├á deux facteurs
          </DialogTitle>
          <DialogDescription>
            Entrez le code ├á 6 chiffres affich├® dans votre application d'authentification.
          </DialogDescription>
        </DialogHeader>

        <div className='space-y-4'>
          {rememberDevice && onRememberDeviceChange && (
            <div className='flex items-center gap-2'>
              <input
                type='checkbox'
                id='remember-device'
                checked={rememberDevice}
                onChange={(e) => onRememberDeviceChange(e.target.checked)}
                className='h-4 w-4 rounded border-gray-300 text-primary focus:ring-primary'
              />
              <Label htmlFor='remember-device' className='text-sm cursor-pointer'>
                Se souvenir de cet appareil pendant 30 jours
              </Label>
            </div>
          )}

          <div className='space-y-2'>
            <Label htmlFor='mfa-code'>Code ├á 6 chiffres :</Label>
            <div className='relative'>
              <Input
                id='mfa-code'
                type={showCode ? 'text' : 'text'}
                inputMode='numeric'
                maxLength={6}
                value={code}
                onChange={(e) => setCode(e.target.value.replace(/[^0-9]/g, '').slice(0, 6))}
                onKeyDown={handleKeyDown}
                placeholder='123456'
                className='text-center text-2xl tracking-widest font-mono py-3'
                autoComplete='one-time-code'
                disabled={isVerifying || isLoading}
                autoFocus
              />
              <Button
                type='button'
                variant='ghost'
                size='icon'
                className='absolute right-3 top-[38px] h-8 w-8'
                onClick={() => setShowCode(!showCode)}
                disabled={isVerifying || isLoading}
                aria-label={showCode ? 'Masquer le code' : 'Afficher le code'}
              >
                {showCode ? <EyeOff className='h-4 w-4' /> : <Eye className='h-4 w-4' />}
              </Button>
            </div>

            {error && (
              <Alert variant='destructive' className='text-sm'>
                <AlertCircle className='h-4 w-4' />
                <AlertDescription>{error}</AlertDescription>
              </Alert>
            )}

            <div className='text-center text-xs text-muted-foreground'>
              Le code se renouvelle toutes les 30 secondes
            </div>
          </div>
        </div>

        <DialogFooter className='gap-2'>
          <Button
            variant='ghost'
            onClick={onCancel}
            disabled={isVerifying || isLoading}
          >
            Annuler
          </Button>
          <Button
            onClick={handleVerify}
            disabled={isVerifying || isLoading || !code || code.length !== 6}
            className='flex-1'
          >
            {isVerifying ? (
              <>
                <Loader2 className='mr-2 h-4 w-4 animate-spin' />
                V├®rification...
              </>
            ) : (
              'V├®rifier'
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

