        </DialogHeader>
        <form onSubmit={handleSubmit} className='space-y-4'>
          <div className='grid grid-cols-2 gap-3'>
            <div className='space-y-2'>
              <Label htmlFor='edit-first'>Pr├®nom</Label>
              <Input
                id='edit-first'
                value={draft.first_name}
                onChange={(e) =>
                  setDraft({ ...draft, first_name: e.target.value })
                }
                required
              />
            </div>
            <div className='space-y-2'>
              <Label htmlFor='edit-last'>Nom</Label>
              <Input
                id='edit-last'
                value={draft.last_name}
                onChange={(e) =>
                  setDraft({ ...draft, last_name: e.target.value })
                }
                required
              />
            </div>
          </div>
          <div className='space-y-2'>
            <Label htmlFor='edit-email'>Adresse email</Label>
            <Input
              id='edit-email'
              type='email'
              value={draft.email}
              onChange={(e) => setDraft({ ...draft, email: e.target.value })}
              required
            />
          </div>
          <div className='space-y-2'>
            <Label htmlFor='edit-phone'>T├®l├®phone</Label>
            <Input
              id='edit-phone'
              type='tel'
              placeholder='+237 6XX XX XX XX'
              value={draft.phone}
              onChange={(e) => setDraft({ ...draft, phone: e.target.value })}
            />
          </div>
          <div className='space-y-2'>
            <Label htmlFor='edit-bio'>Bio</Label>
            <Textarea
              id='edit-bio'
              rows={3}
              placeholder='Une courte description de votre r├┤leÔÇª'
              value={draft.bio}
              onChange={(e) => setDraft({ ...draft, bio: e.target.value })}
              className='resize-none'
            />
          </div>
          <DialogFooter className='gap-2'>
            <Button
              type='button'
              variant='outline'
              onClick={() => onOpenChange(false)}
              disabled={saving}
            >
              Annuler
            </Button>
            <Button type='submit' disabled={!dirty || saving}>
              <Save className='mr-2 h-4 w-4' />
              {saving ? 'EnregistrementÔÇª' : 'Enregistrer'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

function SupportDialog({
