function NotificationsPanel() {
  const items = useNotificationsStore((s) => s.items)
  const markRead = useNotificationsStore((s) => s.markRead)
  const markAllRead = useNotificationsStore((s) => s.markAllRead)
  const [filter, setFilter] = useState<'all' | 'unread' | 'read'>('all')
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set())

  const filteredItems = items.filter((n) => {
    if (filter === 'unread') return !n.read
    if (filter === 'read') return n.read
    return true
  })

  const unreadCount = items.filter((n) => !n.read).length

  const toggleExpanded = (id: string) => {
    setExpandedIds((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const handleMarkAsRead = (id: string) => {
    markRead(id)
  }

  const handleMarkAllAsRead = () => {
    markAllRead()
    toast.success('Toutes les notifications marqu├®es comme lues')
  }

  const getLevelBadge = (level: string) => {
    const variants: Record<string, 'default' | 'secondary' | 'destructive' | 'outline'> = {
      info: 'outline',
      success: 'secondary',
      warning: 'destructive',
      error: 'destructive',
    }
    return (
      <Badge variant={variants[level] || 'outline'} className='text-xs'>
        {level.toUpperCase()}
      </Badge>
    )
  }

  return (
    <Card>
      <CardHeader>
        <div className='flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3'>
          <div>
            <CardTitle className='flex items-center gap-2'>
              <Bell className='h-5 w-5' />
              Notifications
            </CardTitle>
            <CardDescription>
              Centre de notifications. {items.length} notification(s) total, {unreadCount} non lue(s).
            </CardDescription>
          </div>
          <div className='flex flex-wrap items-center gap-2'>
            <Select value={filter} onValueChange={(v) => setFilter(v as typeof filter)}>
              <SelectTrigger className='w-[160px]'>
                <SelectValue placeholder='Toutes' />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value='all'>Toutes ({items.length})</SelectItem>
                <SelectItem value='unread'>Non lues ({unreadCount})</SelectItem>
                <SelectItem value='read'>Lues ({items.length - unreadCount})</SelectItem>
              </SelectContent>
            </Select>
            {unreadCount > 0 && (
              <Button size='sm' variant='ghost' onClick={handleMarkAllAsRead}>
                <CheckCircle2 className='mr-2 h-4 w-4' />
                Tout marquer lu
              </Button>
            )}
          </div>
        </div>
      </CardHeader>
      <CardContent className='p-0'>
        {filteredItems.length === 0 ? (
          <div className='p-8 text-center'>
            <Bell className='h-12 w-12 mx-auto text-muted-foreground/50 mb-3' />
            <p className='text-sm text-muted-foreground'>
              {filter === 'all'
                ? 'Aucune notification pour le moment.'
                : filter === 'unread'
                ? 'Toutes les notifications ont ├®t├® lues !'
                : 'Aucune notification lue pour le moment.'}
            </p>
          </div>
        ) : (
          <ul className='divide-y'>
            {filteredItems.map((n) => {
              const isExpanded = expandedIds.has(n.id)
              return (
                <li
                  key={n.id}
                  className={`flex items-start gap-3 p-4 transition-colors ${
                    !n.read ? 'bg-background' : 'bg-muted/30'
                  }`}
                >
                  <div className='flex flex-col items-center gap-1.5 shrink-0'>
                    <Button
                      variant='ghost'
                      size='icon'
                      className={`size-8 ${
                        !n.read ? 'text-emerald-600 dark:text-emerald-400' : 'text-muted-foreground/50'
                      }`}
                      onClick={() => handleMarkAsRead(n.id)}
                      aria-label={n.read ? 'Marquer comme non lu' : 'Marquer comme lu'}
                    >
                      {n.read ? (
                        <Mail className='h-4 w-4' />
                      ) : (
                        <MailOpen className='h-4 w-4' />
                      )}
                    </Button>
                    <span
                      aria-hidden='true'
                      className={`size-2 shrink-0 rounded-full ${
                        !n.read ? 'bg-emerald-500' : 'bg-slate-400'
                      }`}
                    />
                  </div>
                  <div className='flex-1 min-w-0'>
                    <div className='flex items-start justify-between gap-3'>
                      <div className='flex-1 min-w-0'>
                        <div className='flex items-center gap-2 flex-wrap'>
                          <h4 className={`font-medium leading-none ${!n.read ? 'font-semibold' : ''}`}>
                            {n.title}
                          </h4>
                          {getLevelBadge(n.level)}
                          <span className='text-xs text-muted-foreground'>
                            {new Date(n.ts).toLocaleString(currentLang())}
                          </span>
                        </div>
                        <p className='mt-1 text-sm text-muted-foreground line-clamp-2'>
                          {n.body}
                        </p>
                      </div>
                      <Button
                        variant='ghost'
                        size='icon'
                        className='shrink-0 opacity-0 group-hover:opacity-100'
                        onClick={() => toggleExpanded(n.id)}
                        aria-label={isExpanded ? 'R├®duire' : 'D├®velopper'}
                      >
                        <ChevronDown className={`h-4 w-4 transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
                      </Button>
                    </div>
                  </div>
                  {isExpanded && (
                    <div className='mt-4 ml-10 border-l-2 border-primary/20 pl-4 space-y-2'>
                      <div className='text-xs text-muted-foreground'>
                        <span className='font-medium'>ID: </span>
                        {n.id}
                      </div>
                      {n.level && (
                        <div className='text-xs text-muted-foreground'>
                          <span className='font-medium'>Niveau: </span>
                          {n.level}
                        </div>
                      )}
                      {n.role && (
                        <div className='text-xs text-muted-foreground'>
                          <span className='font-medium'>R├┤le cibl├®: </span>
                          {n.role}
                        </div>
                      )}
                      <div className='flex items-center gap-2'>
                        {!n.read && (
                          <Button size='sm' variant='outline' onClick={() => handleMarkAsRead(n.id)}>
                            <CheckCircle2 className='mr-1.5 h-3.5 w-3.5' />
                            Marquer comme lu
                          </Button>
                        )}
                        <Button
                          size='sm'
                          variant='ghost'
                          onClick={() => {
                            navigator.clipboard.writeText(n.body)
                            toast.success('Notification copi├®e')
                          }}
                        >
                          <Copy className='mr-1.5 h-3.5 w-3.5' />
                          Copier le message
                        </Button>
                      </div>
                    </div>
                  )}
                </li>
              )
            })}
          </ul>
        )}
      </CardContent>
    </Card>
  )
}

function NotificationGroupsPanel() {
  const items = useNotificationGroupsStore((s) => s.items)
  const addGroup = useNotificationGroupsStore((s) => s.addGroup)
  const updateGroup = useNotificationGroupsStore((s) => s.updateGroup)
  const deleteGroup = useNotificationGroupsStore((s) => s.deleteGroup)
  const user = useAuthStore((s) => s.user)
  const [dialogOpen, setDialogOpen] = useState(false)
  const [editingGroup, setEditingGroup] = useState<NotificationGroup | null>(null)
  const [deleteTarget, setDeleteTarget] = useState<NotificationGroup | null>(null)
  const perm = hasPermission(useRoleStore.getState().activeRole, 'notification-groups.write')
  const canWrite = perm

  const handleCreate = (values: NotificationGroupFormValues) => {
    addGroup({
      name: values.name,
      targetRoles: values.targetRoles as Role[],
      createdBy: user?.email ?? 'unknown',
    })
    toast.success(`Groupe "${values.name}" cr├®├®`)
    setDialogOpen(false)
  }

  const handleUpdate = (values: NotificationGroupFormValues) => {
    if (!editingGroup) return
    updateGroup(editingGroup.id, {
      name: values.name,
      targetRoles: values.targetRoles as Role[],
    })
    toast.success(`Groupe "${values.name}" mis ├á jour`)
    setEditingGroup(null)
    setDialogOpen(false)
  }

  const handleDelete = () => {
    if (!deleteTarget) return
    deleteGroup(deleteTarget.id)
    toast.success(`Groupe "${deleteTarget.name}" supprim├®`)
    setDeleteTarget(null)
  }

  const isEditing = editingGroup !== null

  return (
    <Card>
      <CardHeader className='flex flex-row items-start justify-between gap-3 space-y-0'>
        <div>
          <CardTitle>Groupes de notification</CardTitle>
          <CardDescription>
            D├®finissez des ensembles de r├┤les destinataires pour cibler vos
            alertes syst├¿me.
          </CardDescription>
        </div>
        {canWrite && (
          <Button
            type='button'
            size='sm'
            onClick={() => {
              setEditingGroup(null)
              setDialogOpen(true)
            }}
          >
            <Plus className='mr-2 size-4' />
            Nouveau groupe
          </Button>
        )}
      </CardHeader>
      <CardContent>
        {items.length === 0 ? (
          <EmptyState
            title='Aucun groupe'
            description='Cr├®ez votre premier groupe de notification.'
            action={
              canWrite && (
                <Button
                  type='button'
                  size='sm'
                  onClick={() => {
                    setEditingGroup(null)
                    setDialogOpen(true)
                  }}
                >
                  <Plus className='mr-2 size-4' />
                  Nouveau groupe
                </Button>
              )
            }
          />
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Nom</TableHead>
                <TableHead>R├┤les cibles</TableHead>
                <TableHead className='w-[100px]'>Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {items.map((group) => (
                <TableRow key={group.id}>
                  <TableCell className='font-medium'>{group.name}</TableCell>
                  <TableCell>
                    <div className='flex flex-wrap gap-1'>
                      {group.targetRoles.map((role) => (
                        <Badge key={role} variant='outline' className='text-[10px]'>
                          {ROLE_LABELS[role]}
                        </Badge>
                      ))}
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className='flex items-center gap-1'>
                      {canWrite && (
                        <>
                          <Button
                            type='button'
                            variant='ghost'
                            size='icon'
                            className='size-8'
                            onClick={() => {
                              setEditingGroup(group)
                              setDialogOpen(true)
                            }}
                          >
                            <Pencil className='size-3.5' />
                          </Button>
                          <Button
                            type='button'
                            variant='ghost'
                            size='icon'
                            className='size-8 text-destructive'
                            onClick={() => setDeleteTarget(group)}
                          >
                            <Trash2 className='size-3.5' />
                          </Button>
                        </>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </CardContent>

      <Dialog
        open={dialogOpen}
        onOpenChange={(open) => {
          setDialogOpen(open)
          if (!open) setEditingGroup(null)
        }}
      >
        <DialogContent className='sm:max-w-lg'>
          <DialogHeader>
            <DialogTitle>
              {isEditing ? 'Modifier le groupe' : 'Cr├®er un groupe de notification'}
            </DialogTitle>
          </DialogHeader>
          <NotificationGroupForm
            defaultValues={
              isEditing ? groupToFormValues(editingGroup! as NotificationGroup) : undefined
            }
            onSubmit={isEditing ? handleUpdate : handleCreate}
            onCancel={() => {
              setDialogOpen(false)
              setEditingGroup(null)
            }}
            submitLabel={isEditing ? 'Enregistrer' : 'Cr├®er le groupe'}
          />
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={deleteTarget !== null}
        onOpenChange={(open) => {
          if (!open) setDeleteTarget(null)
        }}
        title='Supprimer le groupe'
        desc={
          <span>
            ├ètes-vous s├╗r de vouloir supprimer le groupe{' '}
            <strong>{deleteTarget?.name}</strong> ?
          </span>
        }
        confirmText='Supprimer'
        destructive
        handleConfirm={handleDelete}
      />
    </Card>
  )
}

