                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <DataTablePagination table={table} />
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getFacetedRowModel,
  getFacetedUniqueValues,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  type SortingState,
  type VisibilityState,
  useReactTable,
} from '@tanstack/react-table'
import { cn } from '@/lib/utils'
import { type NavigateFn, useTableUrlState } from '@/hooks/use-table-url-state'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { DataTablePagination, DataTableToolbar } from '@/components/data-table'
import {
  statusLabels,
  supplyView,
  type SupplyRequest,
} from '../data/supply'
import { DataTableBulkActions } from './data-table-bulk-actions'
import { getSupplyColumns } from './supply-columns'

type SupplyTableProps = {
  data: SupplyRequest[]
  search: Record<string, unknown>
  navigate: NavigateFn
}

export function SupplyTable({ data, search, navigate }: SupplyTableProps) {
  const [rowSelection, setRowSelection] = useState({})
  const [columnVisibility, setColumnVisibility] = useState<VisibilityState>({})
  const [sorting, setSorting] = useState<SortingState>([])
  const columns = useMemo(() => getSupplyColumns(), [])

  const statusOptions = useMemo(() => {
    const set = new Set<string>()
    for (const item of supplyView) set.add(item.status)
    return Array.from(set, (status) => ({
      label: statusLabels[status as keyof typeof statusLabels] ?? status,
      value: status,
    }))
  }, [])

  const {
    columnFilters,
    onColumnFiltersChange,
    pagination,
    onPaginationChange,
    ensurePageInRange,
  } = useTableUrlState({
    search,
    navigate,
    pagination: { defaultPage: 1, defaultPageSize: 10 },
    globalFilter: { enabled: false },
    columnFilters: [
      { columnId: 'id', searchKey: 'q', type: 'string' },
      { columnId: 'status', searchKey: 'status', type: 'array' },
      { columnId: 'sourceSiteName', searchKey: 'source', type: 'array' },
      { columnId: 'destSiteName', searchKey: 'dest', type: 'array' },
    ],
  })

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      pagination,
      rowSelection,
      columnFilters,
      columnVisibility,
    },
    enableRowSelection: true,
    onPaginationChange,
    onColumnFiltersChange,
    onRowSelectionChange: setRowSelection,
    onSortingChange: setSorting,
    onColumnVisibilityChange: setColumnVisibility,
    getPaginationRowModel: getPaginationRowModel(),
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFacetedRowModel: getFacetedRowModel(),
    getFacetedUniqueValues: getFacetedUniqueValues(),
  })

  useEffect(() => {
    ensurePageInRange(table.getPageCount())
  }, [table, ensurePageInRange])

  return (
    <div
      className={cn(
        'max-sm:has-[div[role="toolbar"]]:mb-16',
        'flex flex-1 flex-col gap-4'
      )}
    >
      <DataTableToolbar
        table={table}
        searchPlaceholder='Rechercher demande, site, marchand...'
        searchKey='id'
        filters={[
          {
            columnId: 'status',
            title: 'Statut',
            options: statusOptions,
          },
          {
            columnId: 'sourceSiteName',
            title: 'Site source',
            options: statusOptions,
          },
        ]}
      />

      <div className='overflow-hidden rounded-md border'>
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id} className='group/row'>
                {headerGroup.headers.map((header) => (
                  <TableHead
                    key={header.id}
                    colSpan={header.colSpan}
                    className={cn(
                      'bg-background group-hover/row:bg-muted group-data-[state=selected]/row:bg-muted',
                      header.column.columnDef.meta?.className,
                      header.column.columnDef.meta?.thClassName
                    )}
                  >
                    {header.isPlaceholder
                      ? null
                      : flexRender(
                          header.column.columnDef.header,
                          header.getContext()
                        )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && 'selected'}
                  className='group/row'
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell
                      key={cell.id}
                      className={cn(
                        'bg-background group-hover/row:bg-muted group-data-[state=selected]/row:bg-muted',
                        cell.column.columnDef.meta?.className,
                        cell.column.columnDef.meta?.tdClassName
                      )}
                    >
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext()
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={columns.length}
                  className='h-24 text-center'
                >
                  Aucune demande de ramassage ne correspond aux filtres.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <DataTablePagination table={table} className='mt-auto' />
      <DataTableBulkActions table={table} />
    </div>
  )
}

import { useMemo } from 'react'
import { toast } from 'sonner'
import { Button } from '@lpg/ui'
import { hasPermission } from '@lpg/permissions'
import { useRoleStore } from '@/store/role-store'
import { useToursStore } from '@/store/tours-store'
import { type TourActivity, type TourneeStatus, type ExecutionMode } from '../data/tour-activity'
import {
  ACTION_PERMISSION,
  tourActions,
  TOUR_ACTION_LABELS,
  type TourAction,
} from '../data/tour-machine'

const ACTION_VARIANT: Record<TourAction, 'default' | 'outline' | 'destructive'> = {
  'send-to-transporter': 'default',
  acknowledge: 'default',
  plan: 'default',
  start: 'default',
  close: 'default',
  cancel: 'outline',
}

export const STATUS_CLASS: Record<TourneeStatus, string> = {
  DRAFT: 'bg-slate-200 text-slate-800',
  PLANNED: 'bg-sky-100 text-sky-800',
  PENDINGTRANSPORTERACK: 'bg-amber-100 text-amber-900',
  ACKNOWLEDGED: 'bg-violet-100 text-violet-900',
  INPROGRESS: 'bg-blue-500 text-white',
  CHECKPOINTACTIVE: 'bg-orange-500 text-white',
  CLOSED: 'bg-emerald-600 text-white',
  CANCELLED: 'bg-rose-100 text-rose-900',
}

export const MODE_CLASS: Record<ExecutionMode, string> = {
  INTERNAL: 'bg-slate-100 text-slate-700',
  EXTERNAL: 'bg-indigo-100 text-indigo-800',
}

export function TourActions({
  tour,
  onPerformed,
}: {
  tour: TourActivity
  onPerformed?: (next: TourActivity) => void
}) {
  const activeRole = useRoleStore((s) => s.activeRole)
  const actions = useMemo(
    () =>
      tourActions({ status: tour.tourneeStatus, execution_mode: tour.execution_mode })
        .filter(
          (action) => hasPermission(activeRole, ACTION_PERMISSION[action]),
        )
        // acknowledge requires the transporter's crew, captured via the
        // transporter crew-assignment dialog (features/transporters), not a
        // bare status button.
        .filter((action) => action !== 'acknowledge'),
    [tour, activeRole],
  )

  function handleAction(action: TourAction) {
    try {
      const updated = useToursStore.getState().performAction(tour.id, action)
      toast.success(`${tour.reference} ÔÇö ${TOUR_ACTION_LABELS[action]}`)
      onPerformed?.(updated)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Action impossible')
    }
  }

  if (actions.length === 0) return null

  return (
    <div className='flex flex-wrap justify-end gap-2 border-t pt-3'>
      {actions.map((action) => (
        <Button
          key={action}
          variant={ACTION_VARIANT[action]}
          onClick={() => handleAction(action)}
        >
          {TOUR_ACTION_LABELS[action]}
        </Button>
      ))}
    </div>
  )
}

import { type ElementType, useEffect, useMemo, useRef, useState } from 'react'
import { currentLang } from '@/lib/i18n/formatters'
import Graphic from '@arcgis/core/Graphic.js'
import ArcGISMap from '@arcgis/core/Map.js'
