import { useEffect, useMemo, useState } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getExpandedRowModel,
  getFilteredRowModel,
  getGroupedRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  type GroupingState,
  type SortingState,
  useReactTable,
} from '@tanstack/react-table'
import { DataTablePagination, DataTableToolbar } from '@lpg/ui'
import { cn } from '@/lib/utils'
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from '@/components/ui/table'
import { useTranslation } from 'react-i18next'
import { getToursColumns } from './tours-columns'
import { getTourStatusOptions, getExecutionModeOptions, type TourActivity } from '../data/tour-activity'
import { usePreferencesStore } from '@/store/preferences-store'

export function ToursTable({
  rows,
  selectedTripId,
  onOpenDetails,
}: {
  rows: TourActivity[]
  selectedTripId?: string | null
  onOpenDetails: (row: TourActivity) => void
}) {
  const { t } = useTranslation('tours')
  const language = usePreferencesStore((s) => s.language)
  const [sorting, setSorting] = useState<SortingState>([])
  const [grouping, setGrouping] = useState<GroupingState>([])
  const [pagination, setPagination] = useState({ pageIndex: 0, pageSize: 10 })

  const statusOptions = useMemo(() => getTourStatusOptions(t as unknown as never), [t])
  const modeOptions = useMemo(() => getExecutionModeOptions(t as unknown as never), [t])

  const columns = useMemo(
    () => getToursColumns({ onOpenDetails, selectedTripId, t: t as unknown as never, lang: language }),
    [onOpenDetails, selectedTripId, t, language],
  )

  const table = useReactTable({
    data: rows,
    columns,
    state: { sorting, pagination, grouping },
    onSortingChange: setSorting,
    onPaginationChange: setPagination,
    onGroupingChange: setGrouping,
    getExpandedRowModel: getExpandedRowModel(),
    getGroupedRowModel: getGroupedRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
  })

  useEffect(() => {
    setPagination((prev) => ({ ...prev, pageIndex: 0 }))
  }, [grouping, sorting])

  return (
    <div className='flex flex-1 flex-col gap-4'>
      <div className='flex flex-wrap items-center gap-3'>
        <DataTableToolbar
          table={table}
          searchPlaceholder={t('filters.searchPlaceholder', { defaultValue: 'Rechercher une r├®f├®rence, marketeur...' })}
          searchKey='reference'
          filters={[
            { columnId: 'tourneeStatus', title: t('filters.status', { defaultValue: 'Statut' }), options: statusOptions },
            { columnId: 'execution_mode', title: t('filters.mode', { defaultValue: 'Mode' }), options: modeOptions },
          ]}
        />
        <div className='flex items-center gap-2'>
          <span className='text-xs text-muted-foreground'>{t('filters.groupBy', { defaultValue: 'Grouper par' })}</span>
          <select
            value={grouping[0] ?? ''}
            onChange={(e) => setGrouping(e.target.value ? [e.target.value] : [])}
            className='h-8 rounded-md border bg-background px-2 text-sm'
          >
            <option value=''>{t('filters.none', { defaultValue: '--' })}</option>
            <option value='execution_mode'>{t('columns.mode', { defaultValue: 'Mode' })}</option>
            <option value='tourneeStatus'>{t('columns.status', { defaultValue: 'Statut' })}</option>
          </select>
        </div>
      </div>
      <div className='overflow-hidden rounded-md border'>
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead
                    key={header.id}
                    colSpan={header.colSpan}
                    className={cn(header.column.columnDef.meta?.className)}
                  >
                    {header.isPlaceholder ? null : flexRender(header.column.columnDef.header, header.getContext())}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={
                    row.original.id === selectedTripId ? 'selected' : undefined
                  }
                  className={cn(
                    row.original.id === selectedTripId && 'bg-primary/5 hover:bg-primary/10',
                    row.getIsGrouped() && 'bg-muted/40 font-medium',
                  )}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell
                      key={cell.id}
                      className={cn(cell.column.columnDef.meta?.className)}
                    >
                      {cell.getIsGrouped() ? (
                        <button
                          type='button'
                          className='flex items-center gap-2 text-primary'
                          onClick={row.getToggleExpandedHandler()}
                        >
                          {row.getIsExpanded() ? 'Ôû╝' : 'ÔûÂ'} {flexRender(cell.column.columnDef.cell, cell.getContext())} ({row.subRows.length})
                        </button>
                      ) : cell.getIsPlaceholder() ? null : (
                        flexRender(cell.column.columnDef.cell, cell.getContext())
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={columns.length} className='h-24 text-center'>
                  {t('empty', { defaultValue: 'Aucune tourn├®e ne correspond aux filtres.' })}
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <DataTablePagination table={table} className='mt-auto' />
    </div>
  )
}

import { useMemo, useState } from 'react'
import { useTranslation } from 'react-i18next'
import { useNavigate } from '@tanstack/react-router'
import { Plus } from 'lucide-react'
import { Button } from '@lpg/ui'
import { hasPermission } from '@lpg/permissions'
import { PageHeader } from '@/components/layout/page-header'
import { PageShell, SectionCard } from '@/components/layout/page'
import { TourActiveHeader } from './components/tour-active-header'
import { TourCreateWizard } from './components/tour-create-wizard'
import { ToursTable } from './components/tours-table'
import { getTourActivity, type TourSlice } from './data/tour-activity'
import { getScope } from '@/features/scope/scope'
import { useRoleStore } from '@/store/role-store'
import { useAuthStore } from '@/store/auth-store'
import { useToursStore } from '@/store/tours-store'

export function ToursPage() {
  const { t } = useTranslation('tours')
  const navigate = useNavigate()
  const activeRole = useRoleStore((s) => s.activeRole)
  const canCreate = hasPermission(activeRole, 'tours.create')
  const [slice, setSlice] = useState<TourSlice>('ALL')
  const [wizardOpen, setWizardOpen] = useState(false)
  const [selectedId, setSelectedId] = useState<string | undefined>(undefined)

  const slices: { value: TourSlice; label: string }[] = useMemo(
    () => [
      { value: 'ALL', label: t('slices.ALL', { defaultValue: 'Toutes' }) },
      { value: 'INTERNAL', label: t('slices.INTERNAL', { defaultValue: 'Internes' }) },
      { value: 'EXTERNAL', label: t('slices.EXTERNAL', { defaultValue: 'Externalis├®es' }) },
      { value: 'PENDING', label: t('slices.PENDING', { defaultValue: 'En attente' }) },
      { value: 'ACTIVE', label: t('slices.ACTIVE', { defaultValue: 'Actives' }) },
      { value: 'HISTORY', label: t('slices.HISTORY', { defaultValue: 'Historique' }) },
    ],
    [t]
  )

  // Subscribe to the tours store so created / updated tours surface in the
  // table and header (the store is the single source of truth, seeded from
  // the curated fixtures).
  const storeTours = useToursStore((s) => s.tours)
  const storeCheckpoints = useToursStore((s) => s.checkpoints)
  const user = useAuthStore((s) => s.user)
  const scope = useMemo(() => getScope(user), [user])
  const tours = useMemo(
    () => getTourActivity(slice, scope),
    [slice, scope, storeTours, storeCheckpoints],
  )
  const selectedTrip = tours.find((t) => t.id === selectedId) ?? tours[0]

  function openDetail(id: string) {
    navigate({ to: '/tour-tracking/$tourId', params: { tourId: id } })
  }

  return (
    <PageShell>
      <PageHeader
        title={t('title', { defaultValue: 'Tourn├®es de livraison' })}
        description={t('description', { defaultValue: 'Flux 2 ÔÇö livraisons cr├®├®es par les marketeurs et ex├®cut├®es en interne ou par un transporteur.' })}
        actions={
          canCreate ? (
            <Button onClick={() => setWizardOpen(true)} className='gap-1'>
              <Plus className='size-4' /> {t('create', { defaultValue: 'Nouvelle tourn├®e' })}
            </Button>
          ) : undefined
        }
      />
      <TourCreateWizard
        open={wizardOpen}
        onOpenChange={setWizardOpen}
        onCreated={() => {
          /* The tour is written into the tours store, which the page reads
             reactively ÔÇö the new tour surfaces in the table automatically. */
        }}
      />
      {selectedTrip && (
        <TourActiveHeader
          trip={selectedTrip}
          trips={tours}
          onSelectTrip={(id) => setSelectedId(id)}
        />
      )}
      <SectionCard>
        <div className='mb-4 flex flex-wrap gap-2'>
          {slices.map((s) => (
            <button
              key={s.value}
              type='button'
              onClick={() => { setSlice(s.value); setSelectedId(undefined) }}
              className={
                slice === s.value
                  ? 'rounded-full bg-primary px-4 py-2 text-sm font-medium text-primary-foreground'
                  : 'rounded-full border bg-background px-4 py-2 text-sm font-medium text-foreground hover:bg-muted'
              }
            >
              {s.label}
            </button>
          ))}
        </div>
        <ToursTable
          rows={tours}
          selectedTripId={selectedTrip?.id}
          onOpenDetails={(row) => openDetail(row.id)}
        />
      </SectionCard>
    </PageShell>
  )
}

