  const [pagination, setPagination] = useState({ pageIndex: 0, pageSize: 10 })

  const role = useRoleStore((state) => state.activeRole)
  const user = useAuthStore((s) => s.user)
  const scope = useMemo(() => getScope(user), [user])
  const store = useContractsStore((s) => s)
  const columns = useMemo(() => getTransporterContractColumns((row) => {
    const owner = isRegulateurView(scope) || row.marketeur_org_id === scope.orgId
    const transporter = isRegulateurView(scope) || row.transporter_org_id === scope.orgId
    const canWrite = hasPermission(role, 'contracts.write') && owner
    const canValidate = hasPermission(role, 'contracts.validate') && transporter
    const canSuspend = hasPermission(role, 'contracts.suspend') && isRegulateurView(scope)
    const canDelete = hasPermission(role, 'contracts.delete') && owner
    if (!canWrite && !canValidate && !canSuspend && !canDelete) return null
    const run = (message: string, operation: () => void) => {
      try { operation(); toast.success(message) } catch (error) { toast.error(extractErrorMessage(error)) }
    }
    const attach = (file: File | undefined) => {
      if (!file) return
      if (file.type !== 'application/pdf' || file.size > 5 * 1024 * 1024) { toast.error('S├®lectionnez un PDF de 5 Mo maximum'); return }
      const reader = new FileReader()
      reader.onload = () => run('Preuve jointe', () => store.attachProof(row.id, String(reader.result)))
      reader.onerror = () => toast.error('Impossible de lire le fichier PDF')
      reader.readAsDataURL(file)
    }
    return <DropdownMenu><DropdownMenuTrigger asChild><Button variant='ghost' size='icon' aria-label={`Actions ${row.reference}`}><MoreHorizontal className='size-4' /></Button></DropdownMenuTrigger><DropdownMenuContent align='end'><DropdownMenuLabel>Actions</DropdownMenuLabel><DropdownMenuSeparator />
      {canWrite && !row.has_proof ? <DropdownMenuItem onSelect={() => document.getElementById(`proof-${row.id}`)?.click()}>Joindre la preuve<input id={`proof-${row.id}`} type='file' accept='application/pdf' className='hidden' onChange={(event) => attach(event.target.files?.[0])} /></DropdownMenuItem> : null}
      {canValidate && row.has_proof && row.status === 'PENDINGTRANSPORTERACK' ? <DropdownMenuItem onSelect={() => run('Contrat accept├®', () => store.accept(row.id))}>Accepter</DropdownMenuItem> : null}
      {canWrite ? <DropdownMenuItem onSelect={() => onEdit(row.id)}>Modifier</DropdownMenuItem> : null}
      {canSuspend ? <DropdownMenuItem onSelect={() => run(row.is_active ? 'Contrat suspendu' : 'Contrat r├®activ├®', () => row.is_active ? store.suspend(row.id) : store.reactivate(row.id))}>{row.is_active ? 'Suspendre' : 'R├®activer'}</DropdownMenuItem> : null}
      {canWrite && !row.is_primary ? <DropdownMenuItem onSelect={() => run('Contrat principal d├®fini', () => store.setPrimary(row.id))}>D├®finir principal</DropdownMenuItem> : null}
      {canDelete ? <DropdownMenuItem className='text-destructive' onSelect={() => run('Contrat supprim├®', () => store.remove(row.id))}>Supprimer</DropdownMenuItem> : null}
    </DropdownMenuContent></DropdownMenu>
  }), [onEdit, role, scope, store])

  const table = useReactTable({
    data: rows,
    columns,
    state: { sorting, pagination },
    onSortingChange: setSorting,
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
  })

  return (
    <div className='flex flex-1 flex-col gap-4'>
      <DataTableToolbar
        table={table}
        searchPlaceholder='Rechercher un contrat, transporteur...'
        searchKey='reference'
      />
      <div className='overflow-hidden rounded-md border'>
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((hg) => (
              <TableRow key={hg.id}>
                {hg.headers.map((header) => (
                  <TableHead key={header.id} className={cn(header.column.columnDef.meta?.className)}>
                    {header.isPlaceholder ? null : flexRender(header.column.columnDef.header, header.getContext())}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow key={row.id}>
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={columns.length} className='h-24 text-center'>
                  Aucun contrat.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <DataTablePagination table={table} />
    </div>
  )
}

import { useTranslation } from 'react-i18next'
import { useCallback, useMemo, useState } from 'react'
import { currentLang } from '@/lib/i18n/formatters'
import { getRouteApi } from '@tanstack/react-router'
import { CalendarDays, Clock3, Gauge, Plus, Search, Truck as TruckIcon, Users } from 'lucide-react'
import { cn } from '@/lib/utils'
import { useTheme } from '@/context/theme-provider'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { TrucksMap } from './components/trucks-map'
import { TrucksTable } from './components/trucks-table'
import { TruckDetailsSheet } from './components/truck-details-sheet'
import {
  getTruckTelemetry as _getTruckTelemetry,
  getTrucks,
  type Truck,
  type TruckStatus,
} from './data/trucks'
import { EntityFormSheet, resolveListState, useEntityCrud } from '@/components/entity-crud'
import { vehicleFields, vehicleFromForm, vehicleToForm } from '@/features/vehicles/data/vehicles-crud'
import type { Vehicle } from '@lpg/types'
import { runMutation } from '@/hooks/use-toast-feedback'
import { useAuthStore } from '@/store/auth-store'
import { getScope } from '@/features/scope/scope'

export const getTruckTelemetry = _getTruckTelemetry
export type { Truck, TruckStatus }

type TruckFilter = 'all' | TruckStatus

type TruckFilterDef = { label: string; value: TruckFilter; count: number }

const trucksRoute = getRouteApi('/_authenticated/trucks/')

export function TrucksPage() {
  const { t } = useTranslation('common')
  const navigate = trucksRoute.useNavigate()
  const search = trucksRoute.useSearch()
  const { resolvedTheme } = useTheme()
  const [searchText, setSearchText] = useState('')
  const [statusFilter, setStatusFilter] = useState<TruckFilter>('all')
  const [detailsTruck, setDetailsTruck] = useState<Truck | null>(null)
  const user = useAuthStore((s) => s.user)
  const scope = useMemo(() => getScope(user), [user])
  const crud = useEntityCrud<Vehicle>('vehicles', 'trucks', ['vehicles'], true)
  const trucks = useMemo(() => getTrucks(scope, crud.list.data), [scope, crud.list.data])
  const [activeTruckId, setActiveTruckId] = useState<string>(() => trucks[0]?.id ?? '')

  const handleViewDetails = useCallback((truck: Truck) => {
    setDetailsTruck(truck)
  }, [])

  async function handleSubmit(values: Record<string, unknown>) {
    const editing = crud.editing
    if (editing) {
      const result = await runMutation(
        () => crud.updateMut.mutateAsync({ id: editing.id, patch: vehicleFromForm(values) }),
        t('trucks.updated'),
      )
      if (result.ok) crud.close()
    } else {
      const result = await runMutation(
        () => crud.createMut.mutateAsync(vehicleFromForm(values) as Omit<Vehicle, 'id'>),
        t('trucks.created'),
      )
      if (result.ok) crud.close()
    }
  }

  const filteredTrucks = useMemo(() => {
    const query = searchText.trim().toLowerCase()
    if (!query) return [...trucks]
    return trucks.filter((truck) => {
      const haystack = [
        truck.id,
        truck.license_plate,
        truck.assigned_driver,
        truck.region,
        truck.org_id,
        truck.tenant_name,
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase()
      return haystack.includes(query)
    })
  }, [searchText, trucks])

  const visible = statusFilter === 'all' ? filteredTrucks : filteredTrucks.filter((t) => t.tournee_status === statusFilter)
  const listState = resolveListState(
    crud.list.isLoading,
    crud.list.isError,
    visible.length,
    Boolean(searchText.trim() || statusFilter !== 'all'),
  )

  const filterDefs: TruckFilterDef[] = useMemo(() => {
    const counts: Partial<Record<TruckStatus, number>> = {}
    for (const truck of trucks) {
      counts[truck.tournee_status] = (counts[truck.tournee_status] ?? 0) + 1
    }
    return [
      { label: t('trucks.filters.all'), value: 'all', count: trucks.length },
      { label: t('trucks.filters.planned'), value: 'PLANNED', count: counts.PLANNED ?? 0 },
      { label: t('trucks.filters.inProgress'), value: 'INPROGRESS', count: counts.INPROGRESS ?? 0 },
      { label: t('trucks.filters.checkpointActive'), value: 'CHECKPOINTACTIVE', count: counts.CHECKPOINTACTIVE ?? 0 },
      { label: t('trucks.filters.acknowledged'), value: 'ACKNOWLEDGED', count: counts.ACKNOWLEDGED ?? 0 },
      { label: t('trucks.filters.pending'), value: 'PENDINGTRANSPORTERACK', count: counts.PENDINGTRANSPORTERACK ?? 0 },
      { label: t('trucks.filters.closed'), value: 'CLOSED', count: counts.CLOSED ?? 0 },
      { label: t('trucks.filters.cancelled'), value: 'CANCELLED', count: counts.CANCELLED ?? 0 },
    ]
  }, [trucks, t])

  const dateText = useMemo(
    () =>
      new Intl.DateTimeFormat(currentLang(), {
        weekday: 'long',
        day: '2-digit',
        month: 'long',
        year: 'numeric',
      }).format(new Date()),
    []
  )

  const avgLpg = useMemo(() => {
    const list = visible.length > 0 ? visible : trucks
    if (list.length === 0) return 0
    const { sum, count } = list.reduce(
      (acc, truck) => {
        const telemetry = getTruckTelemetry(truck.id)
        const max = truck.type === 'VRAC' ? truck.max_volume : truck.max_bottle_count
        if (!max || max <= 0) return acc
        const pct = Math.round(((telemetry.loaded_quantity ?? 0) / max) * 100)
        return { sum: acc.sum + pct, count: acc.count + 1 }
      },
      { sum: 0, count: 0 },
    )
    return count === 0 ? 0 : Math.round(sum / count)
  }, [visible, trucks])

  const selectedTruck =
    visible.find((t) => t.id === activeTruckId) ?? visible[0] ?? trucks[0]
  const mapTheme = resolvedTheme === 'dark' ? 'dark' : 'light'

  const driverCount = useMemo(
    () =>
      new Set(
        trucks
          .map((t) => t.assigned_driver)
          .filter((d): d is string => Boolean(d && d !== 'ÔÇö')),
      ).size,
    [trucks],
  )

  return (
    <main
      id='main-content'
      className='flex-1 space-y-4 bg-gradient-to-b from-slate-50 via-white to-slate-100 p-4 sm:p-6 dark:from-slate-950 dark:via-slate-950 dark:to-slate-900'
    >
      <section className='rounded-2xl border-transparent bg-background/88 p-3 shadow-sm backdrop-blur-sm sm:p-4'>
        <div className='flex flex-col gap-3 xl:flex-row xl:items-center xl:justify-between'>
          <div className='flex flex-wrap items-center gap-2'>
            <TopStat
              icon={TruckIcon}
              label={t('trucks.kpi.active')}
              value={`${trucks.filter((t) => t.tournee_status === 'INPROGRESS').length}/${trucks.length}`}
            />
            <TopStat
              icon={Users}
              label={t('trucks.kpi.drivers')}
              value={`${driverCount}`}
            />
            <TopStat icon={Gauge} label={t('trucks.kpi.avgLpg')} value={`${avgLpg}%`} />
            <TopStat icon={Clock3} label={t('trucks.kpi.punctuality')} value="94%" hint={t('trucks.kpi.slaGoal')} />
          </div>

          <div className='flex w-full flex-col gap-2 sm:w-auto sm:flex-row sm:items-center'>
            {crud.perm.canCreate && (
              <Button onClick={crud.openCreate}>
                <Plus className='mr-1 h-4 w-4' /> {t('trucks.createButton')}
              </Button>
            )}
            <div className='relative w-full sm:w-[310px]'>
              <Search className='pointer-events-none absolute start-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground' />
              <Input
                aria-label={t('trucks.searchLabel')}
                value={searchText}
                onChange={(e) => setSearchText(e.target.value)}
                placeholder={t('trucks.search')}
                className='h-9 ps-9'
              />
            </div>
          </div>
        </div>

        <div className='mt-4 flex flex-col gap-1'>
          <h1 className='text-[30px] leading-none font-semibold tracking-tight sm:text-3xl'>
            {t('trucks.dashboardTitle')}
          </h1>
          <p className='inline-flex items-center gap-2 text-xs text-muted-foreground sm:text-sm'>
            <CalendarDays className='size-4' />
            {dateText}
          </p>
        </div>
      </section>

      <section className='rounded-2xl border-transparent bg-background/88 p-4 shadow-sm backdrop-blur-sm'>
        <div className='flex flex-wrap gap-2.5'>
          {filterDefs.map((filter) => (
            <FilterChip
              key={filter.value}
              label={filter.label}
              count={filter.count}
              active={statusFilter === filter.value}
              onClick={() => setStatusFilter(filter.value)}
            />
          ))}
        </div>
      </section>

      {selectedTruck ? (
        <section className='relative overflow-hidden rounded-2xl border-transparent bg-muted/70 shadow-sm'>
          <TrucksMap
            sites={[]}
            trucks={visible}
            selectedTruck={selectedTruck}
            mapTheme={mapTheme}
            showRoutes
            onSelectTruck={(truck) => setActiveTruckId(truck.id)}
          />
        </section>
      ) : null}

      <section className='space-y-4 rounded-xl border-transparent bg-background/92 p-4 shadow-sm'>
        <div className='flex flex-col gap-1 sm:flex-row sm:items-end sm:justify-between'>
          <div>
            <h2 className='text-xl font-semibold tracking-tight'>{t('trucks.listTitle')}</h2>
            <p className='text-sm text-muted-foreground'>
              {t('trucks.listDescription')}
            </p>
          </div>
          <Badge
            variant='outline'
            className='border-transparent bg-muted/35 text-foreground'
          >
            {visible.length} / {trucks.length} {t('trucks.countSuffix')}
          </Badge>
        </div>
        <TrucksTable
          data={[...visible]}
          search={search}
          navigate={navigate}
          onViewDetails={handleViewDetails}
          onEdit={(t) => crud.openEdit(t as unknown as Vehicle)}
          onDelete={async (truck) => {
            await runMutation(
              () => crud.removeMut.mutateAsync(truck.id),
              t('entityCrud.deleted'),
            )
          }}
          listState={listState}
          onRetry={() => void crud.list.refetch()}
           deletingId={crud.removeMut.isPending ? crud.removeMut.variables : undefined}

        />
      </section>

      <TruckDetailsSheet
        truck={detailsTruck}
        open={detailsTruck !== null}
        onOpenChange={(open) => {
          if (!open) setDetailsTruck(null)
        }}
      />

      <EntityFormSheet
        open={crud.creating || crud.editing !== null}
        onOpenChange={(open) => {
          if (!open) crud.close()
        }}
        title={crud.editing ? t('trucks.editTitle') : t('trucks.createTitle')}
        description={crud.editing ? t('trucks.editDescription') : t('trucks.createDescription')}
        fields={vehicleFields}
        initial={crud.editing ? vehicleToForm(crud.editing) : null}
        onSubmit={handleSubmit}
        onCancel={crud.close}
        submitting={crud.createMut.isPending || crud.updateMut.isPending}
      />
    </main>
  )
}

function TopStat({
  icon: Icon,
  label,
  value,
  hint,
}: {
  icon: React.ElementType
  label: string
  value: string | number
  hint?: string
}) {
  return (
    <div
      className='inline-flex items-center gap-1.5 rounded-full border-transparent bg-background/90 px-2.5 py-1 text-xs shadow-xs'
      title={hint}
    >
      <Icon className='size-3.5 text-primary' />
      <span className='text-muted-foreground'>{label}</span>
      <span className='font-semibold'>{value}</span>
    </div>
  )
}

function FilterChip({
  label,
  count,
  active,
  onClick,
}: {
  label: string
  count: number
  active: boolean
  onClick: () => void
}) {
  return (
    <Button
      type='button'
      variant={active ? 'default' : 'outline'}
      size='sm'
      className={cn(
        'h-10 rounded-full px-4 text-sm shadow-xs',
        active
          ? 'border-transparent shadow-sm'
          : 'border-transparent bg-background/85 hover:bg-muted/35'
      )}
      onClick={onClick}
    >
      <span>{label}</span>
      <Badge
        className={cn(
          'ms-2 rounded-full px-1.5 py-0 text-[10px]',
          active
            ? 'bg-primary-foreground/20 text-primary-foreground'
            : 'bg-muted text-muted-foreground'
        )}
      >
        {count}
      </Badge>
    </Button>
  )
}

import { useEffect, useMemo, useState } from 'react'
import {
  type GroupingState,
  type SortingState,
  type VisibilityState,
  flexRender,
  getCoreRowModel,
  getExpandedRowModel,
  getFacetedRowModel,
  getFacetedUniqueValues,
  getFilteredRowModel,
  getGroupedRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from '@tanstack/react-table'
import { cn } from '@/lib/utils'
import { type NavigateFn, useTableUrlState } from '@/hooks/use-table-url-state'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { DataTablePagination, DataTableToolbar } from '@/components/data-table'
import type { UserView } from '../data/users'
import { getUsersColumns } from './users-columns'

type UsersTableProps = {
  data: UserView[]
  search: Record<string, unknown>
  navigate: NavigateFn
  onViewDetails: (user: UserView) => void
  onEdit: (user: UserView) => void
}

export function UsersTable({
  data,
  search,
  navigate,
  onViewDetails,
  onEdit,
}: UsersTableProps) {
  const [rowSelection, setRowSelection] = useState({})
  const [columnVisibility, setColumnVisibility] = useState<VisibilityState>({})
  const [sorting, setSorting] = useState<SortingState>([])
  const [grouping, setGrouping] = useState<GroupingState>([])

  const columns = useMemo(
    () => getUsersColumns({ onViewDetails, onEdit }),
    [onViewDetails, onEdit],
  )

  const {
    columnFilters,
    onColumnFiltersChange,
    pagination,
    onPaginationChange,
    ensurePageInRange,
  } = useTableUrlState({
    search,
    navigate,
    pagination: { defaultPage: 1, defaultPageSize: 10 },
    globalFilter: { enabled: false },
    columnFilters: [
      { columnId: 'role', searchKey: 'role', type: 'string' },
      { columnId: 'status', searchKey: 'status', type: 'string' },
    ],
  })

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      pagination,
      rowSelection,
      columnFilters,
      columnVisibility,
      grouping,
    },
    enableRowSelection: true,
    enableGrouping: true,
    onPaginationChange,
    onColumnFiltersChange,
    onRowSelectionChange: setRowSelection,
    onSortingChange: setSorting,
    onColumnVisibilityChange: setColumnVisibility,
    onGroupingChange: setGrouping,
    getPaginationRowModel: getPaginationRowModel(),
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getGroupedRowModel: getGroupedRowModel(),
    getExpandedRowModel: getExpandedRowModel(),
    getFacetedRowModel: getFacetedRowModel(),
    getFacetedUniqueValues: getFacetedUniqueValues(),
  })

  useEffect(() => {
    ensurePageInRange(table.getPageCount())
  }, [table, ensurePageInRange])

  return (
    <div className='flex flex-1 flex-col gap-4'>
       <div className='flex flex-wrap items-center gap-3'>
      <DataTableToolbar
        table={table}
        searchPlaceholder='Rechercher un utilisateur...'
        searchKey='fullName'
        filters={[
          {
            columnId: 'role',
            title: 'R├┤le',
            options: [
              { label: 'Super Admin', value: 'SUPERADMIN' },
              { label: 'Administrateur', value: 'ADMIN' },
              { label: 'Superviseur', value: 'SUPERVISOR' },
              { label: 'Int├®grateur', value: 'INTEGRATEUR' },
              { label: 'Agent validateur', value: 'AGENT' },
              { label: 'Marketeur', value: 'MARKETEUR' },
              { label: 'Transporteur', value: 'TRANSPORTEUR' },
              { label: 'Livreur', value: 'LIVREUR' },
            ],
          },
          {
            columnId: 'status',
            title: 'Statut',
            options: [
              { label: 'Actif', value: 'ACTIVE' },
              { label: 'Inactif', value: 'INACTIVE' },
            ],
          },
        ]}
      />

      <div className='flex items-center gap-2'>
        <span className='text-xs text-muted-foreground'>Grouper par</span>
        <select
          value={grouping[0] ?? ''}
          onChange={(e) => setGrouping(e.target.value ? [e.target.value] : [])}
          className='h-8 rounded-md border bg-background px-2 text-sm'
        >
          <option value=''>ÔÇö</option>
          <option value='role'>R├┤le</option>
          <option value='orgName'>Organisation</option>
          <option value='status'>Statut</option>
          <option value='mfaStatus'>MFA</option>
        </select>
      </div>
      </div>

      <div className='overflow-hidden rounded-md border'>
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id} className='group/row'>
                {headerGroup.headers.map((header) => (
                  <TableHead
                    key={header.id}
                    colSpan={header.colSpan}
                    className={cn(
                      'bg-background group-hover/row:bg-muted group-data-[state=selected]/row:bg-muted',
                      header.column.columnDef.meta?.className,
                    )}
                  >
                    {header.isPlaceholder
                      ? null
                      : flexRender(
                          header.column.columnDef.header,
                          header.getContext(),
                        )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && 'selected'}
                  className={cn(
                    'group/row',
                    row.getIsGrouped() && 'bg-muted/40 font-medium',
                  )}
                  onDoubleClick={() => onViewDetails(row.original)}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell
                      key={cell.id}
                      className={cn(
                        'bg-background group-hover/row:bg-muted group-data-[state=selected]/row:bg-muted',
                        cell.column.columnDef.meta?.tdClassName,
                      )}
                    >
                      {cell.getIsGrouped() ? (
                        <button
                          type='button'
                          className='flex items-center gap-2 text-primary'
                          onClick={row.getToggleExpandedHandler()}
                        >
                          {row.getIsExpanded() ? 'Ôû╝' : 'ÔûÂ'}{' '}
                          {flexRender(
                            cell.column.columnDef.cell,
                            cell.getContext(),
                          )}{' '}
                          ({row.subRows.length})
                        </button>
                      ) : cell.getIsPlaceholder() ? null : (
                        flexRender(
                          cell.column.columnDef.cell,
                          cell.getContext(),
                        )
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={columns.length}
                  className='h-24 text-center'
                >
                  Aucun utilisateur.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      <DataTablePagination table={table} />
    </div>
  )
}

import { useCallback, useMemo, useState } from 'react'
import { currentLang } from '@/lib/i18n/formatters'
import { getRouteApi } from '@tanstack/react-router'
import { useTranslation } from 'react-i18next'
import { CalendarDays, Gauge, Plus, Search, ShieldAlert, Truck as TruckIcon, Users } from 'lucide-react'
import { cn } from '@/lib/utils'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { VehiclesTable } from './components/vehicles-table'
import { VehicleDetailsSheet } from './components/vehicle-details-sheet'
import {
  getVehiclesView,
  type VehicleView,
} from './data/vehicles'
import { activeTourForVehicle, vehicleActiveTourLink } from '@/features/tours/data/active-tour'
import { EntityFormSheet, useEntityCrud } from '@/components/entity-crud'
import { vehicleFields, vehicleFromForm, vehicleToForm } from './data/vehicles-crud'
import { useAuthStore } from '@/store/auth-store'
import { getScope } from '@/features/scope/scope'
import { scopeBySiteOrCreator, scopeWithOrgId } from '@/features/scope/site-creator'
import type { Vehicle } from '@lpg/types'
import { toast } from 'sonner'

export { getVehiclesView }
export type { VehicleView as Vehicle }
export const vehicles: readonly VehicleView[] = getVehiclesView()

type VehicleStatusFilter = 'all' | VehicleView['status']

type VehicleFilterDef = {
  label: string
  value: VehicleStatusFilter
  count: number
}

const statusFilterDefs: readonly {
  label: string
  value: VehicleView['status']
}[] = [
    { label: 'En cours', value: 'INPROGRESS' },
    { label: 'Disponible', value: 'AVAILABLE' },
    { label: 'Planifiee', value: 'PLANNED' },
    { label: 'Etape atteinte', value: 'CHECKPOINTACTIVE' },
    { label: 'Confirmee', value: 'ACKNOWLEDGED' },
    { label: 'Cloturee', value: 'CLOSED' },
    { label: 'Annulee', value: 'CANCELLED' },
  ]

const vehiclesRoute = getRouteApi('/_authenticated/vehicles/')

export function VehiclesPage() {
  const { t } = useTranslation('common')
  const navigate = vehiclesRoute.useNavigate()
  const search = vehiclesRoute.useSearch()
  const { q } = vehiclesRoute.useSearch()
  const [searchText, setSearchText] = useState(q ?? '')
  const [statusFilter, setStatusFilter] = useState<VehicleStatusFilter>('all')
  const [detailsVehicle, setDetailsVehicle] = useState<VehicleView | null>(null)
  const crud = useEntityCrud<Vehicle>('vehicles', 'trucks', ['vehicles'])
  const authUser = useAuthStore((s) => s.user)
  const scopeOrgId = authUser?.org_id
  const allVehicles = getVehiclesView(crud.list.data)
  const scopedVehicles = useMemo(() => {
    const scope = getScope(authUser)
    return scopeBySiteOrCreator(
      allVehicles,
      scopeWithOrgId(scope),
      (v) => v.org_id,
      (v) => v.created_by ?? undefined,
    )
  }, [authUser, allVehicles])

  const handleViewDetails = useCallback((vehicle: VehicleView) => {
    setDetailsVehicle(vehicle)
  }, [])

  async function handleSubmit(values: Record<string, unknown>) {
    try {
      if (crud.editing) {
        await crud.updateMut.mutateAsync({ id: crud.editing.id, patch: vehicleFromForm(values) })
        toast.success('V├®hicule mis ├á jour.')
      } else {
        await crud.createMut.mutateAsync(vehicleFromForm(values) as Omit<Vehicle, 'id'>)
        toast.success('V├®hicule cr├®├®.')
      }
      crud.close()
    } catch {
      toast.error('├ëchec de lÔÇÖenregistrement.')
    }
  }

  const handleOpenActiveTour = useCallback(
    (vehicleId: string) => {
      const link = vehicleActiveTourLink(vehicleId)
      if (!link) return
      const tour = activeTourForVehicle(vehicleId)
      if (!tour) return
      navigate({ to: '/tour-tracking/$tourId', params: { tourId: tour.id } })
    },
    [navigate],
  )

  const filteredVehicles = useMemo(() => {
    const query = searchText.trim().toLowerCase()
    if (!query) return [...scopedVehicles]
    return scopedVehicles.filter((vehicle) => {
      const haystack = [
        vehicle.license_plate,
        vehicle.tenant_name,
        vehicle.assigned_driver,
        vehicle.region,
        vehicle.type,
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase()
      return haystack.includes(query)
    })
  }, [searchText, scopedVehicles])

  const visible =
    statusFilter === 'all'
      ? filteredVehicles
      : filteredVehicles.filter(
          (vehicle) => vehicle.status === statusFilter,
        )

  const filterDefs: VehicleFilterDef[] = useMemo(() => {
    const counts: Partial<Record<VehicleView['status'], number>> = {}
    for (const vehicle of scopedVehicles) {
      counts[vehicle.status] = (counts[vehicle.status] ?? 0) + 1
    }
    const statusDefs = statusFilterDefs.map((def) => ({
      ...def,
      count: counts[def.value] ?? 0,
    }))
    const sortedDefs = [...statusDefs].sort((a, b) => b.count - a.count)
    return [
      { label: 'Tous', value: 'all', count: scopedVehicles.length },
      ...sortedDefs,
    ]
  }, [scopedVehicles])

  const dateText = useMemo(
    () =>
      new Intl.DateTimeFormat(currentLang(), {
        weekday: 'long',
        day: '2-digit',
        month: 'long',
        year: 'numeric',
      }).format(new Date()),
    []
  )

  const avgLpg = useMemo(() => {
    const list = visible.length > 0 ? visible : scopedVehicles
    if (list.length === 0) return 0
    const { sum, count } = list.reduce(
      (acc, vehicle) => {
        const max =
          vehicle.type === 'VRAC'
            ? vehicle.max_volume
            : vehicle.max_bottle_count
        if (!max || max <= 0) return acc
        const loaded = vehicle.loaded_quantity ?? 0
        const pct = Math.round((loaded / max) * 100)
        return { sum: acc.sum + pct, count: acc.count + 1 }
      },
      { sum: 0, count: 0 },
    )
    return count === 0 ? 0 : Math.round(sum / count)
  }, [visible, scopedVehicles])

  const activeCount = useMemo(
    () =>
      scopedVehicles.filter(
        (vehicle) =>
          vehicle.status === 'INPROGRESS' ||
          vehicle.status === 'CHECKPOINTACTIVE',
      ).length,
    [scopedVehicles]
  )

  const atRiskCount = useMemo(
    () =>
      scopedVehicles.filter(
        (vehicle) =>
          vehicle.risk_level === 'CRITIQUE' ||
          vehicle.risk_level === 'CRITIQUEEXTREME' ||
          vehicle.risk_level === 'ELEVE',
      ).length,
    [scopedVehicles]
  )

  return (
    <main
      id='main-content'
      className='flex-1 space-y-4 bg-gradient-to-b from-slate-50 via-white to-slate-100 p-4 sm:p-6 dark:from-slate-950 dark:via-slate-950 dark:to-slate-900'
    >
      <section className='rounded-2xl border-transparent bg-background/88 p-3 shadow-sm backdrop-blur-sm sm:p-4'>
        <div className='flex flex-col gap-3 xl:flex-row xl:items-center xl:justify-between'>
          <div className='flex flex-wrap items-center gap-2'>
            <TopStat
              icon={TruckIcon}
              label='Actifs'
              value={`${activeCount}/${scopedVehicles.length}`}
            />
            <TopStat
              icon={Users}
              label='Chauffeurs'
              value={`${scopedVehicles.filter((v) => v.assigned_driver !== 'ÔÇö').length}`}
              hint='Affectes au parc'
            />
            <TopStat icon={Gauge} label='LPG moyen' value={`${avgLpg}%`} />
            <TopStat icon={ShieldAlert} label='A surveiller' value={atRiskCount} />
          </div>

          <div className='flex w-full flex-col gap-2 sm:w-auto sm:flex-row sm:items-center'>
            {crud.perm.canCreate && (
              <Button onClick={crud.openCreate}>
                <Plus className='mr-1 h-4 w-4' /> {t('vehicles.createTitle')}
              </Button>
            )}
            <div className='relative w-full sm:w-[310px]'>
              <Search className='pointer-events-none absolute start-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground' />
              <Input
                value={searchText}
                onChange={(e) => setSearchText(e.target.value)}
                placeholder='Rechercher plaque, entreprise, chauffeurÔÇª'
                className='h-9 ps-9'
              />
            </div>
          </div>
        </div>

        <div className='mt-4 flex flex-col gap-1'>
          <h1 className='text-[30px] leading-none font-semibold tracking-tight sm:text-3xl'>
            Flotte de vehicules
          </h1>
          <p className='inline-flex items-center gap-2 text-xs text-muted-foreground sm:text-sm'>
            <CalendarDays className='size-4' />
            {dateText}
          </p>
        </div>
      </section>

      <section className='rounded-2xl border-transparent bg-background/88 p-4 shadow-sm backdrop-blur-sm'>
        <div className='flex flex-wrap gap-2.5'>
          {filterDefs.map((filter) => (
            <FilterChip
              key={filter.value}
              label={filter.label}
              count={filter.count}
              active={statusFilter === filter.value}
              onClick={() => setStatusFilter(filter.value)}
            />
          ))}
        </div>
      </section>

      <section className='space-y-4 rounded-xl border-transparent bg-background/92 p-4 shadow-sm'>
        <div className='flex flex-col gap-1 sm:flex-row sm:items-end sm:justify-between'>
          <div>
            <h2 className='text-xl font-semibold tracking-tight'>
              Liste des vehicules
            </h2>
            <p className='text-sm text-muted-foreground'>
              Selectionnez un vehicule pour voir sa fiche detaillee, son
              certificat et sa mission courante.
            </p>
          </div>
          <Badge
            variant='outline'
            className='border-transparent bg-muted/35 text-foreground'
          >
            {visible.length} / {scopedVehicles.length} vehicules
          </Badge>
        </div>
        <VehiclesTable
          data={[...visible]}
          search={search}
          navigate={navigate}
          onViewDetails={handleViewDetails}
          onOpenActiveTour={handleOpenActiveTour}
          onEdit={(v) => crud.openEdit(v as unknown as Vehicle)}
          onDelete={async (v) => {
            await crud.removeMut.mutateAsync(v.id)
          }}
        />
      </section>

      <VehicleDetailsSheet
        vehicle={detailsVehicle}
        open={detailsVehicle !== null}
        onOpenChange={(open) => {
          if (!open) setDetailsVehicle(null)
        }}
      />

      <EntityFormSheet
        open={crud.creating || crud.editing !== null}
        onOpenChange={(open) => {
          if (!open) crud.close()
        }}
        title={crud.editing ? t('vehicles.editTitle') : t('vehicles.createTitle')}
        description={crud.editing ? 'Mettez ├á jour les informations du v├®hicule.' : 'Ajoutez un v├®hicule ├á la flotte.'}
        fields={vehicleFields}
        initial={crud.editing ? vehicleToForm(crud.editing) : scopeOrgId ? { org_id: scopeOrgId } : null}
        onSubmit={handleSubmit}
        onCancel={crud.close}
        submitting={crud.createMut.isPending || crud.updateMut.isPending}
      />
    </main>
  )
}

function TopStat({
  icon: Icon,
  label,
  value,
  hint,
}: {
  icon: React.ElementType
  label: string
  value: string | number
  hint?: string
}) {
  return (
    <div
      className='inline-flex items-center gap-1.5 rounded-full border-transparent bg-background/90 px-2.5 py-1 text-xs shadow-xs'
      title={hint}
    >
      <Icon className='size-3.5 text-primary' />
      <span className='text-muted-foreground'>{label}</span>
      <span className='font-semibold'>{value}</span>
    </div>
  )
}

function FilterChip({
  label,
  count,
  active,
  onClick,
}: {
  label: string
  count: number
  active: boolean
  onClick: () => void
}) {
  return (
    <Button
      type='button'
      variant={active ? 'default' : 'outline'}
      size='sm'
      className={cn(
        'h-10 rounded-full px-4 text-sm shadow-xs',
        active
          ? 'border-transparent shadow-sm'
          : 'border-transparent bg-background/85 hover:bg-muted/35'
      )}
      onClick={onClick}
    >
      <span>{label}</span>
      <Badge
        className={cn(
          'ms-2 rounded-full px-1.5 py-0 text-[10px]',
          active
            ? 'bg-primary-foreground/20 text-primary-foreground'
            : 'bg-muted text-muted-foreground'
        )}
      >
        {count}
      </Badge>
    </Button>
  )
}

