  search: Record<string, unknown>
  navigate: NavigateFn
  onViewDetails: (zone: ZoneView) => void
  onViewMap: (zone: ZoneView) => void
  onEdit?: (zone: ZoneView) => void
  onDelete?: (zone: ZoneView) => void | Promise<void>
  canDelete?: boolean
