export function ZonesTable({
  data,
  search,
  navigate,
  onViewDetails,
  onViewMap,
  onEdit,
  onDelete,
  canDelete = false,
}: ZonesTableProps) {
  const { t } = useTranslation('common')
  const [rowSelection, setRowSelection] = useState({})
  const [columnVisibility, setColumnVisibility] = useState<VisibilityState>({})
  const [sorting, setSorting] = useState<SortingState>([])

  const columns = useMemo<ColumnDef<ZoneView>[]>(
    () => [
      {
        accessorKey: 'code',
        header: 'Code',
        cell: ({ row }: { row: { original: ZoneView } }) => (
          <Badge variant='outline' className='font-mono'>
            {row.original.code}
          </Badge>
        ),
        meta: { label: 'Code' },
      },
      {
        accessorKey: 'name',
        header: ({ column }: { column: { toggleSorting: (asc?: boolean) => void; getIsSorted: () => boolean | 'asc' | 'desc' } }) => (
          <Button
            variant='ghost'
            onClick={() => column.toggleSorting(column.getIsSorted() === 'asc')}
            className='h-8 px-2'
          >
            Nom
          </Button>
        ),
        cell: ({ row }: { row: { original: ZoneView } }) => (
          <Button
            variant='link'
            className='h-auto p-0 font-normal'
            onClick={() => onViewDetails(row.original)}
          >
            {row.original.name}
          </Button>
        ),
      },
      {
        accessorKey: 'siteCount',
        header: 'Sites',
        cell: ({ row }: { row: { original: ZoneView } }) => row.original.siteCount,
        meta: { label: 'Sites' },
      },
      {
        accessorKey: 'clientSiteCount',
        header: 'Sites clients',
        cell: ({ row }: { row: { original: ZoneView } }) => row.original.clientSiteCount,
        meta: { label: 'Sites clients' },
      },
      {
        id: 'actions',
        header: '',
        enableHiding: false,
        enableSorting: false,
        cell: ({ row }: { row: { original: ZoneView } }) => (
          <div className='flex justify-end'>
            <CrudRowActions
              resource='zones'
              itemLabel='cette zone'
              onEdit={onEdit ? () => onEdit(row.original) : undefined}
              onDelete={canDelete && onDelete ? () => onDelete(row.original) : undefined}
              extra={[{ label: 'Voir sur la carte', onSelect: () => onViewMap(row.original) }]}
            />
          </div>
        ),
        meta: { label: 'Actions' },
      },
    ],
    [canDelete, onDelete, onEdit, onViewDetails, onViewMap],
  )

  const {
    columnFilters,
    onColumnFiltersChange,
    pagination,
    onPaginationChange,
    ensurePageInRange,
  } = useTableUrlState({
    search,
    navigate,
    pagination: { defaultPage: 1, defaultPageSize: 10 },
    globalFilter: { enabled: false },
    columnFilters: [
      { columnId: 'name', searchKey: 'name', type: 'string' },
    ],
  })

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      pagination,
      rowSelection,
      columnFilters,
      columnVisibility,
    },
    enableRowSelection: true,
    onPaginationChange,
    onColumnFiltersChange,
    onRowSelectionChange: setRowSelection,
    onSortingChange: setSorting,
    onColumnVisibilityChange: setColumnVisibility,
    getPaginationRowModel: getPaginationRowModel(),
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFacetedRowModel: getFacetedRowModel(),
    getFacetedUniqueValues: getFacetedUniqueValues(),
  })

  useEffect(() => {
    ensurePageInRange(table.getPageCount())
  }, [table, ensurePageInRange])

  return (
    <div className='flex flex-1 flex-col gap-4'>
      <DataTableToolbar
        table={table}
        searchPlaceholder={t('search.zone')}
        searchKey='name'
        filters={[
          {
            columnId: 'code',
            title: 'R├®gion',
            options: getZoneOptions(),
          },
        ]}
      />

      <div className='overflow-hidden rounded-md border'>
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id} className='group/row'>
                {headerGroup.headers.map((header) => (
                  <TableHead
                    key={header.id}
                    colSpan={header.colSpan}
                    className={cn(
                      'bg-background group-hover/row:bg-muted group-data-[state=selected]/row:bg-muted',
                      header.column.columnDef.meta?.className,
                    )}
                  >
                    {header.isPlaceholder
                      ? null
                      : flexRender(
                          header.column.columnDef.header,
                          header.getContext(),
                        )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && 'selected'}
                  className='group/row'
                  onDoubleClick={() => onViewDetails(row.original)}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell
                      key={cell.id}
                      className={cn(
                        'bg-background group-hover/row:bg-muted group-data-[state=selected]/row:bg-muted',
                        cell.column.columnDef.meta?.tdClassName,
                      )}
                    >
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={columns.length}
                  className='h-24 text-center'
                >
                  Aucune zone.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      <DataTablePagination table={table} />
    </div>
  )
}

import { describe, expect, it } from 'vitest'
import { getZodErrorMap } from './zod'

function getMessage(map: ReturnType<typeof getZodErrorMap>, issue: any): string {
  const res = (map as unknown as (a: any, b: any) => any)(issue, { defaultError: 'x', data: undefined })
  if (typeof res === 'string') return res
  return res?.message ?? ''
}

describe('getZodErrorMap', () => {
  it('returns French for invalid_type undefined', () => {
    const map = getZodErrorMap('fr-FR')
    const issue = { code: 'invalid_type', expected: 'string', received: 'undefined' } as any
    expect(getMessage(map, issue)).toBe('Champ requis')
  })
  it('returns English for invalid_type undefined', () => {
    const map = getZodErrorMap('en-US')
    const issue = { code: 'invalid_type', expected: 'string', received: 'undefined' } as any
    expect(getMessage(map, issue)).toBe('Required')
  })
  it('returns French for invalid email', () => {
    const map = getZodErrorMap('fr-FR')
    const issue = { code: 'invalid_string', validation: 'email' } as any
    expect(getMessage(map, issue)).toBe('Email invalide')
  })
  it('returns English for invalid email', () => {
    const map = getZodErrorMap('en-US')
    const issue = { code: 'invalid_string', validation: 'email' } as any
    expect(getMessage(map, issue)).toBe('Invalid email')
  })
  it('returns French for too_small', () => {
    const map = getZodErrorMap('fr-FR')
    const issue = { code: 'too_small', minimum: 3, type: 'string', inclusive: true } as any
    expect(getMessage(map, issue)).toBe('Minimum 3')
  })
  it('returns English for too_small', () => {
    const map = getZodErrorMap('en-US')
    const issue = { code: 'too_small', minimum: 5, type: 'string', inclusive: true } as any
    expect(getMessage(map, issue)).toBe('Minimum 5')
  })
})

import type { LanguagePreference } from '@/store/preferences-store'
import type { ZodErrorMap } from 'zod'

export function getZodErrorMap(lang: LanguagePreference): ZodErrorMap {
  return ((issue: any, ctx: any) => {
    const fr = lang === 'fr-FR'
    const isUndefined =
      issue.received === 'undefined' || (issue.code === 'invalid_type' && issue.input === undefined)
    if (issue.code === 'invalid_type' && isUndefined) return { message: fr ? 'Champ requis' : 'Required' }
    if (issue.code === 'too_small') return { message: fr ? `Minimum ${issue.minimum}` : `Minimum ${issue.minimum}` }
    if (
      (issue.code === 'invalid_string' && issue.validation === 'email') ||
      (issue.code === 'invalid_format' && issue.format === 'email')
    )
      return { message: fr ? 'Email invalide' : 'Invalid email' }
    if (
      (issue.code === 'invalid_string' && issue.validation === 'url') ||
      (issue.code === 'invalid_format' && issue.format === 'url')
    )
      return { message: fr ? 'URL invalide' : 'Invalid URL' }
    return { message: ctx?.defaultError ?? issue.message ?? '' }
  }) as unknown as ZodErrorMap
}

