import { createFileRoute } from '@tanstack/react-router'
import { useMemo } from 'react'
import { useRoleStore } from '@/store/role-store'
import { useAuthStore } from '@/store/auth-store'
import { useToursStore } from '@/store/tours-store'
import { getScope } from '@/features/scope/scope'
import { buildDashboardView } from '@/features/dashboard/data/dashboard'
import { OverviewPage } from '@/features/overview'
import { RouteSkeleton } from '@/components/layout/route-skeleton'
import { GeneralError } from '@/features/errors/general-error'

function OverviewRouteComponent() {
  const role = useRoleStore((s) => s.activeRole)
  const user = useAuthStore((s) => s.user)
  const storeTours = useToursStore((s) => s.tours)
  const storeCheckpoints = useToursStore((s) => s.checkpoints)
  const scope = useMemo(() => getScope(user), [user])
  const dashboard = useMemo(
    () => buildDashboardView(role, scope),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [role, scope, storeTours, storeCheckpoints]
  )
  return <OverviewPage role={role} dashboard={dashboard} />
}

export const Route = createFileRoute('/_authenticated/overview/')({
  component: OverviewRouteComponent,
  pendingComponent: RouteSkeleton,
  errorComponent: GeneralError,
})

import { createFileRoute, redirect, useNavigate } from '@tanstack/react-router'
import { AuthenticatedLayout } from '@/components/layout/authenticated-layout'
import { useAuthStore } from '@/store/auth-store'
import { type Role } from '@/config/rbac/roles'
import { canAccessPath, deniedPathRedirect } from '@/config/rbac/route-access'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'

export const Route = createFileRoute('/_authenticated')({
  beforeLoad: async ({ location }) => {
    const { accessToken, hydrateSession } = useAuthStore.getState()
    if (!accessToken) {
      await hydrateSession()
    }
    const auth = useAuthStore.getState()
    const token = auth.accessToken
    if (!token) {
      throw redirect({
        to: '/login',
      })
    }
    // Defense-in-depth: nav visibility alone must not guarantee access.
    // Store the denied-redirect target in the route context for the component
    // to render an alert dialog before navigating.
    const role = auth.user?.system_role as Role | undefined
    if (role && !canAccessPath(role, location.pathname)) {
      return { deniedTo: deniedPathRedirect(role, location.pathname) }
    }
    return { deniedTo: null }
  },
  component: AuthenticatedRouteGuard,
})

function AuthenticatedRouteGuard() {
  const { deniedTo } = Route.useRouteContext()
  const navigate = useNavigate()

  if (deniedTo) {
    return (
      <AlertDialog open={true}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Acc├¿s refus├®</AlertDialogTitle>
            <AlertDialogDescription>
              Vous n'avez pas la permission d'acc├®der ├á cette page. Redirection
              vers l'aper├ºu.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogAction
              onClick={() => navigate({ to: deniedTo })}
            >
              Continuer
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    )
  }

  return <AuthenticatedLayout />
}

import { createFileRoute, redirect } from '@tanstack/react-router'
import { currentLang } from '@/lib/i18n/formatters'
import { useState } from 'react'
import {
  Button,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@lpg/ui'
import { Plus, Pencil, Trash2, Users } from 'lucide-react'
import { PageShell, EmptyState } from '@/components/layout/page'
import { PageHeader } from '@/components/layout/page-header'
import { useAuthStore } from '@/store/auth-store'
import { ROLE_LABELS } from '@/config/rbac/roles'
import type { Role } from '@/config/rbac/roles'
import { hasPermission } from '@lpg/permissions'
import { ConfirmDialog } from '@/components/confirm-dialog'
import {
  useNotificationGroupsStore,
  type NotificationGroup,
} from '@/features/notifications/notification-groups-store'
import {
  NotificationGroupForm,
  groupToFormValues,
} from '@/features/notifications/notification-group-form'
import type { NotificationGroupFormValues } from '@/features/notifications/notification-group-schema'
import { toast } from 'sonner'

export const Route = createFileRoute('/_authenticated/settings/notification-groups')({
  beforeLoad: () => {
    const role = useAuthStore.getState().user?.system_role as Role | undefined
    if (!role || !hasPermission(role, 'notification-groups.write')) {
      throw redirect({ to: '/settings/profile' })
    }
  },
  component: NotificationGroupsPage,
})

function formatDate(ts: number): string {
  return new Date(ts).toLocaleString(currentLang(), {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  })
}

function NotificationGroupsPage() {
  const items = useNotificationGroupsStore((s) => s.items)
  const addGroup = useNotificationGroupsStore((s) => s.addGroup)
  const updateGroup = useNotificationGroupsStore((s) => s.updateGroup)
  const deleteGroup = useNotificationGroupsStore((s) => s.deleteGroup)
  const user = useAuthStore((s) => s.user)

  const [dialogOpen, setDialogOpen] = useState(false)
  const [editingGroup, setEditingGroup] = useState<NotificationGroup | null>(null)
  const [deleteTarget, setDeleteTarget] = useState<NotificationGroup | null>(null)

  const handleCreate = (values: NotificationGroupFormValues) => {
    addGroup({
      name: values.name,
      targetRoles: values.targetRoles as Role[],
      createdBy: user?.email ?? 'unknown',
    })
    toast.success(`Groupe "${values.name}" cr├®├®`)
    setDialogOpen(false)
  }

  const handleUpdate = (values: NotificationGroupFormValues) => {
    if (!editingGroup) return
    updateGroup(editingGroup.id, {
      name: values.name,
      targetRoles: values.targetRoles as Role[],
    })
    toast.success(`Groupe "${values.name}" mis ├á jour`)
    setEditingGroup(null)
    setDialogOpen(false)
  }

  const handleDelete = () => {
    if (!deleteTarget) return
    deleteGroup(deleteTarget.id)
    toast.success(`Groupe "${deleteTarget.name}" supprim├®`)
    setDeleteTarget(null)
  }

  const openEdit = (group: NotificationGroup) => {
    setEditingGroup(group)
    setDialogOpen(true)
  }

  const isEditing = editingGroup !== null

  return (
    <PageShell>
      <PageHeader
        title='Groupes de notification'
        icon={Users}
        description='Cr├®ez et g├®rez des groupes de destinataires pour les notifications.'
        actions={
          <Button
            type='button'
            size='sm'
            onClick={() => {
              setEditingGroup(null)
              setDialogOpen(true)
            }}
          >
            <Plus className='size-4' />
            Cr├®er un groupe
          </Button>
        }
      />

      <Card className='mt-6'>
        <CardHeader className='pb-3'>
          <CardTitle className='text-base'>Groupes existants</CardTitle>
          <CardDescription>
            {items.length === 0
              ? 'Aucun groupe de notification cr├®├® pour le moment.'
              : `${items.length} groupe${items.length > 1 ? 's' : ''} de notification`}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {items.length === 0 ? (
            <EmptyState
              title='Aucun groupe'
              description='Cr├®ez votre premier groupe de notification pour cibler plusieurs r├┤les ├á la fois.'
              action={
                <Button
                  type='button'
                  variant='outline'
                  size='sm'
                  onClick={() => {
                    setEditingGroup(null)
                    setDialogOpen(true)
                  }}
                >
                  <Plus className='size-4' />
                  Cr├®er un groupe
                </Button>
              }
            />
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Nom</TableHead>
                  <TableHead>R├┤les cibles</TableHead>
                  <TableHead>Cr├®├® par</TableHead>
                  <TableHead>Cr├®├® le</TableHead>
                  <TableHead className='w-[100px]'>Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {items.map((group) => (
                  <TableRow key={group.id}>
                    <TableCell className='font-medium'>{group.name}</TableCell>
                    <TableCell>
                      <div className='flex flex-wrap gap-1'>
                        {group.targetRoles.map((role) => (
                          <span
                            key={role}
                            className='inline-flex items-center rounded-full border px-2 py-0.5 text-xs font-medium text-muted-foreground'
                          >
                            {ROLE_LABELS[role]}
                          </span>
                        ))}
                      </div>
                    </TableCell>
                    <TableCell className='text-sm text-muted-foreground'>
                      {group.createdBy}
                    </TableCell>
                    <TableCell className='text-sm text-muted-foreground'>
                      {formatDate(group.createdAt)}
                    </TableCell>
                    <TableCell>
                      <div className='flex items-center gap-1'>
                        <Button
                          type='button'
                          variant='ghost'
                          size='icon'
                          className='size-8'
                          onClick={() => openEdit(group)}
                        >
                          <Pencil className='size-3.5' />
                        </Button>
                        <Button
                          type='button'
                          variant='ghost'
                          size='icon'
                          className='size-8 text-destructive'
                          onClick={() => setDeleteTarget(group)}
                        >
                          <Trash2 className='size-3.5' />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      <Dialog
        open={dialogOpen}
        onOpenChange={(open) => {
          setDialogOpen(open)
          if (!open) setEditingGroup(null)
        }}
      >
        <DialogContent className='sm:max-w-lg'>
          <DialogHeader>
            <DialogTitle>
              {isEditing ? 'Modifier le groupe' : 'Cr├®er un groupe de notification'}
            </DialogTitle>
          </DialogHeader>
          <NotificationGroupForm
            defaultValues={isEditing ? groupToFormValues(editingGroup! as NotificationGroup) : undefined}
            onSubmit={isEditing ? handleUpdate : handleCreate}
            onCancel={() => {
              setDialogOpen(false)
              setEditingGroup(null)
            }}
            submitLabel={isEditing ? 'Enregistrer' : 'Cr├®er le groupe'}
          />
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        open={deleteTarget !== null}
        onOpenChange={(open) => {
          if (!open) setDeleteTarget(null)
        }}
        title='Supprimer le groupe'
        desc={
          <span>
            ├ètes-vous s├╗r de vouloir supprimer le groupe{' '}
            <strong>{deleteTarget?.name}</strong> ? Cette action est irr├®versible.
          </span>
        }
        confirmText='Supprimer'
        destructive
        handleConfirm={handleDelete}
      />
    </PageShell>
  )
}

